@mainmenu_group.command("edit")
@click.option("--output-dir", type=click.Path(), default=None)
def mainmenu_edit(output_dir):
    """Interactive editor — accept commands at a prompt and confirm on quit.

    \b
    Commands available at the prompt:
      up N            move row N up
      down N          move row N down
      move N to M     move row N to position M (1-indexed)
      hide N | show N toggle visibility for row N
      add NAME        append a new system
      remove N        delete row N
      sort alpha|manufacturer|year
      list            re-render the table
      q | quit        exit (prompts to save if dirty)
    """
    from .mainmenu import (
        add_system, hide, move_down, move_up, remove_system, reorder,
        show as _show, sort_alphabetical, sort_by_field,
    )
    config = _cfg()
    _check_config(config)
    menu = _load_menu_or_exit(config)
    dirty = False

    def render():
        console.print(_render_menu_table(menu, config))

    console.print(Panel(" Main Menu editor ", style="bold blue"))
    render()
    console.print(
        "[dim]commands: up N | down N | move N to M | hide N | show N | "
        "add NAME | remove N | sort alpha|manufacturer|year | list | q[/dim]"
    )

    while True:
        try:
            line = click.prompt("mainmenu>", default="", show_default=False).strip()
        except click.exceptions.Abort:
            console.print("\n[yellow]Aborted.[/yellow]")
            return
        if not line:
            continue
        parts = line.split()
        cmd = parts[0].lower()

        try:
            if cmd in {"q", "quit", "exit"}:
                break
            elif cmd == "list":
                render()
            elif cmd == "up" and len(parts) == 2:
                move_up(menu, _resolve_target(menu, parts[1]))
                dirty = True
                render()
            elif cmd == "down" and len(parts) == 2:
                move_down(menu, _resolve_target(menu, parts[1]))
                dirty = True
                render()
            elif cmd == "move" and len(parts) == 4 and parts[2].lower() == "to":
                target_sys = _resolve_target(menu, parts[1])
                reorder(menu, target_sys, int(parts[3]))
                dirty = True
                render()
            elif cmd == "hide" and len(parts) == 2:
                hide(menu, _resolve_target(menu, parts[1]))
                dirty = True
                render()
            elif cmd == "show" and len(parts) == 2:
                _show(menu, _resolve_target(menu, parts[1]))
                dirty = True
                render()
            elif cmd == "add" and len(parts) >= 2:
                name = " ".join(parts[1:])
                if add_system(menu, name):
                    dirty = True
                    render()
                else:
                    console.print(f"[yellow]already on the menu:[/yellow] {name}")
            elif cmd == "remove" and len(parts) == 2:
                target_sys = _resolve_target(menu, parts[1])
                if remove_system(menu, target_sys):
                    dirty = True
                    render()
            elif cmd == "sort" and len(parts) == 2:
                strat = parts[1].lower()
                if strat == "alpha":
                    sort_alphabetical(menu)
                elif strat in {"manufacturer", "year", "genre"}:
                    sort_by_field(menu, strat)
                else:
                    console.print(f"[red]unknown sort:[/red] {strat}")
                    continue
                dirty = True
                render()
            else:
                console.print(f"[red]unrecognised command:[/red] {line}")
        except (KeyError, ValueError, click.UsageError) as e:
            console.print(f"[red]{e}[/red]")

    if not dirty:
        console.print("[dim]No changes.[/dim]")
        return
    if not click.confirm("Save changes to Main Menu.xml?", default=True):
        console.print("[yellow]Discarded.[/yellow]")
        return
    _save_with_message(menu, config, output_dir)


# ─── doctor ───────────────────────────────────────────────────────────────────

@cli.command("doctor")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Apply safe, idempotent repairs (default: read-only diagnosis). "
                   "Repairs include: pruning stale match cache, creating missing "
                   "media folders, regenerating Global Emulators.ini if missing. "
                   "Never deletes ROMs/DBs/media.")
def doctor(apply_changes):
    """Self-diagnose: paths, binaries, DB integrity, cache hygiene, integrations.

    Pass --apply to perform safe, idempotent repairs.
    """
    from rich.tree import Tree
    from .health import Status, run_health_checks

    config = _cfg()
    report = run_health_checks(config, fix=apply_changes)

    icon_for = {
        Status.OK: "[green]✓[/green]",
        Status.WARN: "[yellow]⚠[/yellow]",
        Status.FAIL: "[red]✗[/red]",
        Status.INFO: "[dim]i[/dim]",
    }

    tree = Tree("[bold]SpinDoctor health[/bold]")

    def render(check, parent):
        label = f"{icon_for[check.status]} [bold]{check.name}[/bold]"
        if check.detail:
            label += f"  [dim]·[/dim] {check.detail}"
        node = parent.add(label)
        if check.fix and not apply_changes:
            node.add(f"[dim]fix:[/dim] {check.fix}")
        for ch in check.children:
            render(ch, node)

    for c in report.checks:
        render(c, tree)

    console.print(tree)

    if report.fixes_applied:
        console.print("\n[green bold]Fixes applied:[/green bold]")
        for f in report.fixes_applied:
            console.print(f"  [green]+[/green] {f}")

    overall = report.overall()
    console.print(
        f"\nOverall: {icon_for[overall]} "
        f"[bold]{overall.value.upper()}[/bold]"
    )
    if overall == Status.FAIL:
        sys.exit(2)


@cli.command("self-doctor")
@click.option(
    "--fix", is_flag=True,
    help="Delete stale rescue copies and orphan .part files older than "
         "the documented thresholds (30 days / 7 days). Never touches "
         "config.json, current backups, manifests, or the metadata cache.",
)
def self_doctor(fix):
    """Diagnose SpinDoctor's own state (not the cabinet library).

    `spindoctor doctor` checks the library. This command checks the
    state SpinDoctor accumulates inside `~/.spindoctor/` — orphan
    backup folders, corrupt-config rescue copies, manifest dirs,
    expired metadata cache, leftover `.part` files. Read-only by
    default; pass `--fix` to clean up the categories explicitly
    flagged as safe to delete.
    """
    from .self_doctor import Status as _S, render_report, run_self_checks

    config = _cfg()
    report = run_self_checks(config, fix=fix)
    render_report(report, console)
    if report.overall() == _S.FAIL:
        sys.exit(2)


# ─── ledblinky ────────────────────────────────────────────────────────────────

@cli.group("ledblinky")
def ledblinky_group():
    """Generate and audit LEDBlinky controls.ini / colors.ini.

    \b
    Subcommands:
      generate       Generate / merge Controls.ini and Colors.ini from MAME data
      audit          Audit ROM → Colors.ini coverage
      check          Check LEDBlinky compatibility with HyperSpin
      fix            Fix LEDBlinky compatibility issues
      patch-settings Patch Settings.ini to suppress unused-button flash
      fill-defaults  Add default Colors.ini entries for ROMs with no LED mapping
      admin-buttons  Set per-button admin/cabinet colors across all ROM sections
      colors         Manage named color definitions (list / edit / normalize)
    """


@ledblinky_group.command("generate")
@click.option("--system", "-s", default="MAME",
              help="System to generate for (default: MAME).")
@click.option("--overwrite", is_flag=True,
              help="Overwrite existing entries (default: keep community-maintained ones).")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--output-dir", type=click.Path(), default=None,
              help="Write to this directory instead of <ledblinky_dir>.")
@click.option("--verbose", is_flag=True, help="Print the controls and colors file paths written.")
def ledblinky_generate(system, overwrite, apply_changes, output_dir, verbose):
    """Generate / merge LEDBlinky controls.ini and colors.ini.

    Strategy: existing entries from <ledblinky_dir> are preserved verbatim;
    ROMs not yet covered get synthesized entries derived from
    `mame -listxml`.
    """
    config = _cfg()
    _check_config(config)

    if not config.mame_executable:
        err_console.print(
            "[red]mame_executable is not configured.[/red]  "
            "Run: spindoctor config set mame_executable /path/to/mame"
        )
        sys.exit(1)

    from .audit import scan_roms
    from .ledblinky import generate_for_roms

    rom_dir = Path(config.roms_dir) / system
    roms = scan_roms(system, Path(config.roms_dir))
    if not roms:
        console.print(
            f"[yellow]No ROMs found for system [cyan]{system}[/cyan] "
            f"in [cyan]{rom_dir}[/cyan].[/yellow] "
            "Drop ROM files there and re-run."
        )
        return

    out_path = Path(output_dir) if output_dir else None
    try:
        result = generate_for_roms(
            config,
            rom_names=sorted(roms.keys()),
            output_dir=out_path,
            overwrite_existing=overwrite,
            dry_run=not apply_changes,
        )
    except ValueError as e:
        err_console.print(f"[red]{e}[/red]")
        sys.exit(1)

    for w in result.warnings:
        console.print(f"[yellow]WARNING:[/yellow] {w}")
    label = "[green]wrote[/green]" if apply_changes else "[yellow]would write[/yellow]"
    console.print(f"\n{label} controls.ini → {result.controls_path}")
    console.print(f"{label} colors.ini   → {result.colors_path}")
    console.print(
        f"  Synthesised: [cyan]{result.controls_synthesised}[/cyan] controls, "
        f"[cyan]{result.colors_synthesised}[/cyan] colors"
    )
    console.print(
        f"  Kept existing: [dim]{result.controls_existing_kept}[/dim] controls, "
        f"[dim]{result.colors_existing_kept}[/dim] colors"
    )
    if result.skipped_no_input:
        console.print(
            f"  Skipped (no -listxml input data): [yellow]{result.skipped_no_input}[/yellow]"
        )
    # Warn if Color-RGB.ini was missing (colors written in legacy format)
    has_legacy_warning = any("ledcolor=" in w or "P1_BUTTON1=" in w for w in result.warnings)
    if not has_legacy_warning and result.colors_synthesised:
        console.print(
            "[dim]  colors.ini written in native P1_BUTTON1= format "
            "(Color-RGB.ini palette used for color name lookup)[/dim]"
        )
    if verbose:
        console.print(f"\n[dim][verbose] controls → {result.controls_path}[/dim]")
        console.print(f"[dim][verbose] colors   → {result.colors_path}[/dim]")
        if result.colors_synthesised:
            fmt = "legacy ledcolor=" if has_legacy_warning else "native P1_BUTTON1="
            console.print(f"[dim][verbose] colors format: {fmt}[/dim]")


@ledblinky_group.command("inspect-rom")
@click.argument("rom_name")
def ledblinky_inspect_rom(rom_name):
    """Diagnose why a ROM's LED colors may not be applying.

    Reads Colors.ini, controls.ini, LEDBlinkyControls.xml, and MAME listxml
    for the given ROM and reports what LEDBlinky would see — including
    mismatches, missing entries, and the path to LEDBlinky's own log file
    (written by LEDBlinky itself, not SpinDoctor).

    When output_dir is configured the full report is also saved there as
    ``<output_dir>/diagnostics/inspect-rom-<ROM>-<timestamp>.txt``.

    \b
    This is the first command to run when game colors are showing white or
    not changing from the default.

    \b
    Examples:
      spindoctor ledblinky inspect-rom 005
      spindoctor ledblinky inspect-rom 1942
    """
    from datetime import datetime as _dt
    from . import ledblinky as lb

    config = _cfg()
    data = lb.inspect_rom(config, rom_name)

    # Build the report as plain text so we can both print and optionally save it.
    lines: list[str] = []

    def _pr(text: str = "") -> None:
        """Print to console AND accumulate for the optional saved report."""
        lines.append(text)
        console.print(text)

    _pr(f"\n[blue bold]LEDBlinky ROM Inspection — [{rom_name}][/blue bold]")

    # Colors.ini
    _pr(f"\n[bold]Colors.ini[/bold]  {data['colors_ini_path']}")
    if data["colors_entry"]:
        _pr(f"  [green]✓ Found[/green] [{rom_name}] — {len(data['colors_entry'])} key(s):")
        for line in data["colors_entry"]:
            _pr(f"    [dim]{line}[/dim]")
    else:
        _pr(f"  [red]✗ NOT FOUND[/red] — LEDBlinky will use DEFAULT colors")

    # controls.ini
    _pr(f"\n[bold]controls.ini[/bold]  {data['controls_ini_path']}")
    if data["controls_entry"]:
        _pr(f"  [green]✓ Found[/green] [{rom_name}] — {len(data['controls_entry'])} key(s):")
        for line in data["controls_entry"]:
            _pr(f"    [dim]{line}[/dim]")
    else:
        _pr(f"  [yellow]⚠ NOT FOUND[/yellow] — LEDBlinky won't know which buttons this game uses")

    # LEDBlinkyControls.xml
    _pr(f"\n[bold]LEDBlinkyControls.xml[/bold]  {data['xml_path']}")
    if data["xml_emulators"]:
        _pr(f"  Emulators in XML: {', '.join(data['xml_emulators'])}")
    if data["xml_rom_entries"]:
        _pr(f"  [green]✓ ROM entry found:[/green]")
        for entry in data["xml_rom_entries"]:
            _pr(f"    tag={entry['tag']}  emulator={entry['emulator']}")
            for k, v in entry["attrs"].items():
                _pr(f"      {k}={v}")
    else:
        _pr(
            f"  [yellow]⚠ No entry for [{rom_name}][/yellow] — "
            f"LEDBlinky uses DEFAULT control group. "
            f"Colors.ini overrides may not apply."
        )

    # MAME listxml
    _pr(f"\n[bold]MAME listxml[/bold]")
    if data["listxml"]:
        lx = data["listxml"]
        _pr(f"  [green]✓ Found[/green] — {lx['description']}")
        _pr(f"    Players: {lx['players']}  Buttons: {lx['buttons']}  "
            f"Controls: {', '.join(lx['controls']) or 'none'}")
    else:
        _pr(f"  [dim]Not found in MAME listxml (MAME not configured or ROM not in DB)[/dim]")

    # LEDBlinky's own log (written by LEDBlinky, not SpinDoctor)
    _pr(f"\n[bold]LEDBlinky log[/bold]  (written by LEDBlinky itself — not SpinDoctor)")
    _pr(f"  Path: {data['log_path']}")
    if data["log_path"] and Path(str(data["log_path"])).exists():
        _pr(
            f"  [green]✓ Log exists[/green] — open it and search for [{rom_name}] "
            f"to see what name LEDBlinky received when the game last launched."
        )
    else:
        _pr(
            f"  [yellow]⚠ Log not found[/yellow] — enable logging in LEDBlinky Settings "
            f"to capture game-launch events and verify the ROM name being sent."
        )

    # Warnings / diagnostics
    if data["warnings"]:
        _pr(f"\n[bold]Diagnostics[/bold]")
        for w in data["warnings"]:
            if "NOT FOUND" in w or "NOT found" in w or "not found" in w:
                _pr(f"  [yellow]⚠[/yellow] {w}")
            elif "case" in w.lower():
                _pr(f"  [red]✗[/red] {w}")
            else:
                _pr(f"  [dim]·[/dim] {w}")

    # Summary guidance
    _pr(f"\n[bold]What to check next[/bold]")
    if not data["colors_entry"]:
        _pr(
            "  1. Run [cyan]spindoctor ledblinky colors normalize --apply[/cyan] "
            "to ensure Colors.ini is in native format, then re-run generate+randomize."
        )
    if not data["xml_rom_entries"]:
        _pr(
            "  2. Open LEDBlinkyControls.xml and check the MAME emulator entry. "
            "If Colors.ini overrides are not applying, your version of LEDBlinky "
            "may require per-game XML entries, not just Colors.ini sections."
        )
    _pr(
        "  3. Open the LEDBlinky log and search for the game name to verify "
        "what name RocketLauncher sends to LEDBlinky at game launch. "
        "The name must exactly match the Colors.ini section header."
    )
    _pr(
        "  4. In LEDBlinky's main UI, check Settings → 'Use Color File' is enabled."
    )

    # Save report to output_dir if configured
    if getattr(config, "output_dir", ""):
        try:
            stamp = _dt.now().strftime("%Y%m%d_%H%M%S")
            out_dir = Path(config.output_dir) / "diagnostics"
            out_dir.mkdir(parents=True, exist_ok=True)
            report_path = out_dir / f"inspect-rom-{rom_name}-{stamp}.txt"
            # Strip Rich markup for the saved file
            import re as _re
            plain = _re.sub(r"\[/?[^\]]+\]", "", "\n".join(lines))
            report_path.write_text(plain, encoding="utf-8")
            console.print(f"\n[dim]Report saved: {report_path}[/dim]")
        except OSError as exc:
            err_console.print(f"[yellow]Could not save report to output_dir: {exc}[/yellow]")


@ledblinky_group.command("audit")
@click.option("--system", "-s", default="MAME")
def ledblinky_audit(system):
    """Show LEDBlinky coverage per ROM (covered / would-synth / no-input / missing)."""
    config = _cfg()
    _check_config(config)

    from .audit import scan_roms
    from .ledblinky import audit_coverage

    rom_dir = Path(config.roms_dir) / system
    roms = scan_roms(system, Path(config.roms_dir))
    if not roms:
        console.print(
            f"[yellow]No ROMs found for system [cyan]{system}[/cyan] "
            f"in [cyan]{rom_dir}[/cyan].[/yellow] "
            "Drop ROM files there and re-run."
        )
        return

    rows = audit_coverage(config, sorted(roms.keys()))

    counts = {"covered": 0, "would-synth": 0, "no-input": 0, "missing": 0}
    for r in rows:
        counts[r.status] = counts.get(r.status, 0) + 1

    summary = Table(title=f"LEDBlinky coverage — {system}", box=box.ROUNDED)
    summary.add_column("Status", style="cyan")
    summary.add_column("Count", justify="right")
    summary.add_row("[green]Covered (controls.ini + colors.ini)[/green]", str(counts["covered"]))
    summary.add_row("[yellow]Would synthesise from -listxml[/yellow]", str(counts["would-synth"]))
    summary.add_row("[dim]Game has no input[/dim]", str(counts["no-input"]))
    summary.add_row("[red]Not in -listxml[/red]", str(counts["missing"]))
    console.print(summary)

    missing_or_synth = [r for r in rows if r.status in ("would-synth", "missing")]
    if missing_or_synth:
        tbl = Table(box=box.SIMPLE, show_header=True)
        tbl.add_column("ROM", style="cyan")
        tbl.add_column("In -listxml", justify="center")
        tbl.add_column("controls.ini", justify="center")
        tbl.add_column("colors.ini", justify="center")
        tbl.add_column("Status")
        for r in missing_or_synth[:60]:
            tbl.add_row(
                r.rom_name,
                _status(r.in_listxml),
                _status(r.in_controls_ini),
                _status(r.in_colors_ini),
                r.status,
            )
        console.print(tbl)
        if len(missing_or_synth) > 60:
            console.print(f"  [dim]... and {len(missing_or_synth) - 60} more[/dim]")


# ─── report ───────────────────────────────────────────────────────────────────

@cli.command("report")
@click.option("--system", "-s", default=None)
@click.option("--all", "all_systems", is_flag=True)
@click.option("--format", "fmt", default="summary",
              type=click.Choice(["table", "csv", "summary"]))
@click.option("--output", "-o", type=click.Path(), default=None)
@click.option("--no-media", is_flag=True)
@click.option("--no-fuzzy", is_flag=True)
def report(system, all_systems, fmt, output, no_media, no_fuzzy):
    """Generate a read-only audit report without making any changes."""
    config = _cfg()
    _check_config(config)
    systems = _resolve_systems(config, system, all_systems)

    all_results: list[SystemAuditResult] = []
    with _make_progress(SpinnerColumn(), TextColumn("{task.description}"), console=console) as prog:
        task = prog.add_task("Scanning…", total=len(systems))
        for sys_name in systems:
            prog.update(task, description=f"Scanning [cyan]{sys_name}[/cyan]…")
            all_results.append(
                audit_system(sys_name, config,
                             check_media_flag=not no_media,
                             fuzzy=not no_fuzzy)
            )
            prog.advance(task)

    if fmt == "csv":
        if not output:
            err_console.print("[red]--output is required for CSV format.[/red]")
            sys.exit(1)
        _write_audit_csv(all_results, Path(output))
        console.print(f"[green]Report written:[/green] {output}")
        return

    if fmt == "summary":
        tbl = Table(title="Audit Summary", box=box.ROUNDED)
        tbl.add_column("System", style="cyan")
        tbl.add_column("ROMs", justify="right")
        tbl.add_column("DB", justify="right")
        tbl.add_column("Match", justify="right", style="green")
        tbl.add_column("Fuzzy", justify="right", style="blue")
        tbl.add_column("ROM only", justify="right", style="yellow")
        tbl.add_column("DB only", justify="right", style="red")
        tbl.add_column("No meta", justify="right", style="magenta")
        tbl.add_column("No media", justify="right", style="magenta")
        tbl.add_column("Ignored", justify="right", style="dim")
        for r in all_results:
            tbl.add_row(
                r.system_name,
                str(r.total_roms), str(r.total_db_entries),
                str(r.roms_in_db), str(len(r.fuzzy_matches)),
                str(r.roms_not_in_db), str(r.db_entries_no_rom),
                str(len(r.missing_metadata_entries)),
                str(len(r.missing_media_entries)),
                str(r.ignored_count),
            )
        console.print(tbl)
        if output:
            with open(output, "w", encoding="utf-8") as f:
                from rich.console import Console as RC
                RC(file=f, no_color=True).print(tbl)
            console.print(f"[green]Report written:[/green] {output}")
        return

    for r in all_results:
        _print_audit_result(r, show_matched=False)
    if output:
        _write_audit_csv(all_results, Path(output))
        console.print(f"[green]Report written:[/green] {output}")


# ─── preview ──────────────────────────────────────────────────────────────────

@cli.command("preview")
@click.option("--system", "-s", default=None,
              help="System to render (use --all to do every system).")
@click.option("--all", "all_systems", is_flag=True,
              help="One subfolder per system inside --output-dir.")
@click.option("--output-dir", "-o", type=click.Path(), required=True,
              help="Where to write the index.html / cards / index.png.")
@click.option("--format", "fmt", default="html",
              type=click.Choice(["html", "png", "both"]),
              help="Contact-sheet output format. PNG requires Pillow.")
@click.option("--columns", default=6, type=int,
              help="Contact-sheet column count (default 6).")
@click.option("--include-missing", is_flag=True,
              help="Show games with no wheel as a placeholder cell.")
@click.option("--game", "single_game", default=None,
              help="Render only this game's card (no contact sheet).")
@click.option("--open", "open_in_browser", is_flag=True,
              help="Open the index in the default browser when done.")
def preview_cmd(system, all_systems, output_dir, fmt, columns,
                include_missing, single_game, open_in_browser):
    """Generate visual previews of a system's wheels / themes / media.

    \b
    Two output modes:
      • Contact sheet — grid of every wheel (HTML or PNG).
      • Per-game card — full-page mock of a HyperSpin entry (HTML).

    \b
    Examples:
      spindoctor preview --system MAME --output-dir D:\\Preview
      spindoctor preview --all --output-dir D:\\Preview --format both
      spindoctor preview --system NES --output-dir D:\\Out --game "Super Mario Bros"
      spindoctor preview --system NES --output-dir D:\\Out --open
    """
    import webbrowser

    from .preview import (
        collect_previews,
        collect_previews_including_missing,
        render_game_card_html,
        render_system_overview,
        pillow_available,
    )

    config = _cfg()
    _check_config(config)

    if fmt in ("png", "both") and not pillow_available():
        console.print(
            "[yellow]Pillow not installed — PNG output will fall back to HTML. "
            "Install with: pip install -e .[preview][/yellow]"
        )

    if single_game and (all_systems or not system):
        err_console.print(
            "[red]--game requires --system NAME (one system at a time).[/red]"
        )
        sys.exit(1)

    out_base = Path(output_dir)
    systems = _resolve_systems(config, system, all_systems)

    formats: tuple[str, ...]
    if fmt == "html":
        formats = ("html",)
    elif fmt == "png":
        formats = ("png",)
    else:
        formats = ("html", "png")

    opened = False
    primary_index: Optional[Path] = None

    for sys_name in systems:
        items = (
            collect_previews_including_missing(sys_name, config)
            if include_missing
            else collect_previews(sys_name, config)
        )

        if single_game:
            match = next((i for i in items if i.game_name == single_game), None)
            if match is None:
                # Try display-name match.
                match = next(
                    (i for i in items if i.display_name == single_game), None,
                )
            if match is None:
                err_console.print(
                    f"[red]No game named '{single_game}' in {sys_name}.[/red]"
                )
                sys.exit(1)
            target = out_base / f"{single_game}.html"
            render_game_card_html(match, target)
            console.print(f"[green]Wrote card:[/green] {target}")
            primary_index = target
            continue

        sys_dir = out_base / sys_name if all_systems else out_base
        if not items:
            console.print(
                f"[yellow]{sys_name}: no games with media to preview.[/yellow]"
            )
            continue

        result = render_system_overview(
            sys_name, items, sys_dir,
            columns=columns,
            include_missing=include_missing,
            formats=formats,
        )
        console.print(
            f"[green]{sys_name}:[/green] {len(result['cards'])} card(s) · "
            f"index: {result['index_html']}"
            + (f" · png: {result['index_png']}" if result['index_png'] else "")
        )
        if primary_index is None:
            primary_index = result["index_html"]

    if open_in_browser and primary_index is not None and not opened:
        webbrowser.open(primary_index.resolve().as_uri())


# ─── ledblinky: HyperSpin Search compatibility (check / fix) ──────────────────

@ledblinky_group.command("check")
@click.option("--menus", default="Search",
              help="Comma-separated special menus to check. Default: Search.")
def ledblinky_check(menus):
    """Scan HyperSpin + LedBlinky configs for known Search-menu conflicts."""
    from . import ledblinky as lb

    config = _cfg()
    menu_list = [m.strip() for m in menus.split(",") if m.strip()]
    result = lb.scan(config, menus=menu_list)

    tbl = Table(title="LedBlinky compatibility scan", box=box.ROUNDED)
    tbl.add_column("Check", style="cyan")
    tbl.add_column("Result")

    tbl.add_row(
        "ledblinky_dir",
        f"{_status(result['ledblinky_dir_exists'])} "
        f"{config.ledblinky_dir or '[dim]<not set>[/dim]'}",
    )
    tbl.add_row(
        "LEDBlinkyControls.xml",
        f"{_status(result['controls_xml_exists'])} "
        f"{result['controls_xml_path'] or '[dim]—[/dim]'}",
    )

    for info in result["menu_inis"]:
        hooks = info["has_hooks"]
        in_xml = info["has_controls_entry"]
        tbl.add_row(
            f"{info['menu']} menu INI",
            f"exists={_status(info['exists'])}  "
            f"hooks={'[red]yes[/red]' if hooks else '[green]no[/green]'}  "
            f"in controls.xml={_status(in_xml)}",
        )

    if result["global_settings_ini"]:
        tbl.add_row(
            "HyperSpin Settings.ini hooks",
            "[dim]present (expected — left untouched)[/dim]"
            if result["global_settings_has_hooks"]
            else "[dim]absent[/dim]",
        )

    console.print(tbl)

    if result["ok"]:
        console.print("[green]✓ No issues detected.[/green]")
        return

    console.print("\n[yellow bold]Issues:[/yellow bold]")
    for issue in result["issues"]:
        console.print(f"  • {issue}")
    console.print(
        "\nRun [cyan]spindoctor ledblinky fix[/cyan] to preview the patch "
        "(re-run with [cyan]--apply[/cyan] to commit)."
    )


@ledblinky_group.command("fix")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit the patch (default: dry-run preview).")
@click.option("--output-dir", type=click.Path(), default=None,
              help="Write patched files here instead of in-place.")
@click.option("--no-backup", is_flag=True,
              help="Skip .bak backups when writing in-place.")
@click.option("--menus", default="Search",
              help="Comma-separated special menus to patch. Default: Search. "
                   "Other options: Genre, Favorites.")
def ledblinky_fix(apply_changes, output_dir, no_backup, menus):
    """Fix LEDBlinky overlay hooks so Search / Genre / Favorites don't hang HyperSpin.

    \b
    When LedBlinky hooks are active, HyperSpin's Search, Genre, and Favorites
    overlays can freeze or crash because LedBlinky tries to look up controls for
    a system name that doesn't exist in LEDBlinkyControls.xml.  Two patches fix
    this:

      1. LEDBlinkyControls.xml — adds a stub entry for each requested menu
         (Search, Genre, Favorites) so LedBlinky's lookup finds it and continues.
      2. HyperSpin per-menu Settings.ini — comments out any
         Start_Hyperspin_Process / Exit_Hyperspin_Process lines that launch or
         kill LEDBlinky.exe when the overlay opens/closes.  If the Settings.ini
         does not exist, there are no hooks to remove — this is not an error.

    \b
    Writes in-place to ledblinky_dir and hyperspin_dir (not to output_dir).
    Use --output-dir only when you want to preview the patched files without
    touching your live cabinet install.

    \b
    Examples:
      spindoctor ledblinky fix                              :: preview (default)
      spindoctor ledblinky fix --apply                      :: commit in-place
      spindoctor ledblinky fix --apply --menus Search,Genre,Favorites
      spindoctor ledblinky fix --apply --output-dir D:\\Output  :: write to D:\\Output (test)
    """
    from . import ledblinky as lb

    config = _cfg()
    _check_config(config)
    # ledblinky fix is an in-place patcher — do NOT fall back to config.output_dir.
    # Only use an explicit --output-dir when one is passed on the command line.
    out_base = Path(output_dir) if output_dir else None
    menu_list = [m.strip() for m in menus.split(",") if m.strip()]

    if not apply_changes:
        console.print(
            "[yellow bold][DRY RUN][/yellow bold] No files will be written. "
            "Re-run with [cyan]--apply[/cyan] to commit."
        )

    result = lb.apply_fix(
        config,
        output_base=out_base,
        dry_run=not apply_changes,
        backup=not no_backup,
        menus=menu_list,
    )

    # Show config paths used so the user can verify they point to the right places.
    console.print(f"\n[dim]ledblinky_dir : {config.ledblinky_dir or '[not set]'}[/dim]")
    console.print(f"[dim]hyperspin_dir : {config.hyperspin_dir or '[not set]'}[/dim]")

    cx = result["controls_xml"]
    console.print("\n[blue bold]LEDBlinkyControls.xml[/blue bold]")
    if cx is None:
        console.print("  [dim]skipped (ledblinky_dir not set)[/dim]")
    elif cx["added"]:
        verb = "Added" if apply_changes and cx["wrote"] else "Would add"
        console.print(f"  [green]{verb}[/green] entries: {', '.join(cx['added'])}")
        console.print(f"  Path: {cx['path']}")
    else:
        console.print("  [green]✓ Already contains all requested menu entries.[/green]")

    console.print("\n[blue bold]HyperSpin per-menu INIs[/blue bold]")
    console.print(
        "[dim]  (path: <hyperspin_dir>\\Menu\\<MenuName>\\Settings.ini — "
        "removes LEDBlinky process hooks that cause HyperSpin to hang "
        "when Search / Genre / Favorites overlays open)[/dim]"
    )
    tbl = Table(box=box.SIMPLE, show_header=True)
    tbl.add_column("Menu", style="cyan")
    tbl.add_column("Path")
    tbl.add_column("Hook lines", justify="right")
    tbl.add_column("Status")
    for info in result["menu_inis"]:
        if info.get("error"):
            # "not found" is non-fatal — it just means HyperSpin has never written
            # LEDBlinky hooks into that menu's Settings.ini, so there's nothing to remove.
            err_text = info["error"]
            if "not found" in err_text:
                status = "[dim]✓ no Settings.ini → no hooks to remove[/dim]"
            else:
                status = f"[yellow]{err_text}[/yellow]"
            tbl.add_row(info["menu"], str(info["src"]), "—", status)
            continue
        if info["lines_changed"] == 0:
            status = "[green]✓ no hooks found[/green]"
        elif apply_changes and info["wrote"]:
            status = "[green]patched[/green]"
        else:
            status = "[yellow]would patch[/yellow]"
        tbl.add_row(
            info["menu"],
            str(info["path"]),
            str(info["lines_changed"]),
            status,
        )
    console.print(tbl)

    if result["errors"]:
        console.print("\n[red]Errors:[/red]")
        for e in result["errors"]:
            console.print(f"  • {e}")

    if apply_changes and result["backup"]:
        console.print(
            "\n[dim]Backups saved as <file>.YYYYMMDD_HHMMSS.bak next to each modified file.[/dim]"
        )


@ledblinky_group.command("patch-settings")
@click.option(
    "--fe-lwa", default=None,
    help="LWA animation filename for the frontend idle state (FELWAFile in "
         "[FEOptions]).  E.g. 'Slow Fade.lwa'.  Pass empty string to stop "
         "all animation and show static colors.  Omit to leave unchanged.",
)
@click.option(
    "--game-lwa", default="",
    help="LWA animation filename for in-game unassigned buttons "
         "(GamePlayLWAFile in [GameOptions]).  Default: '' (empty) which "
         "turns off random flashing on unused buttons during gameplay.",
)
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit the patch (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip the .bak backup when writing in-place.")
@click.option("--verbose", is_flag=True, help="Print the settings file path being patched.")
def ledblinky_patch_settings(fe_lwa, game_lwa, apply_changes, no_backup, verbose):
    """Patch Settings.ini to fix idle animation and silence unused buttons.

    \b
    Patches two keys in Settings.ini by default:

      GamePlayLWAFile (in [GameOptions])
        Animation on unassigned buttons DURING gameplay.
        Default: "" (empty) — unused buttons go dark instead of flashing.

      FELWAFile (in [FEOptions])
        Animation while browsing HyperSpin (omit flag to leave unchanged).
        Pass a .lwa filename for a smooth fade, or "" for static colors.

    \b
    Examples:
      spindoctor ledblinky patch-settings               # preview only
      spindoctor ledblinky patch-settings --apply       # fix in-game flash
      spindoctor ledblinky patch-settings --fe-lwa "Slow Fade.lwa" --apply
      spindoctor ledblinky patch-settings --fe-lwa "" --apply  # static FE
    """
    from . import ledblinky as lb

    config = _cfg()
    _check_config(config)

    if not apply_changes:
        console.print(
            "[yellow bold][DRY RUN][/yellow bold] No files will be written. "
            "Re-run with [cyan]--apply[/cyan] to commit."
        )

    try:
        result = lb.patch_ledblinky_settings(
            config,
            fe_lwa_file=fe_lwa,
            game_play_lwa_file=game_lwa,
            dry_run=not apply_changes,
            backup=not no_backup,
        )
    except ValueError as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1) from exc

    console.print(f"\n[blue bold]Settings.ini[/blue bold]  {result.settings_path}")

    if not result.changes:
        console.print(
            "  [green]✓ No changes needed — already at the requested values.[/green]"
        )
    else:
        for change in result.changes:
            verb = (
                "[yellow]would change[/yellow]"
                if result.dry_run
                else "[green]changed[/green]"
            )
            console.print(f"  {verb}: {change}")
            if verbose:
                console.print(f"[dim][verbose] Settings.ini: {result.settings_path}[/dim]")
                if result.changes:
                    console.print(f"[dim][verbose] keys patched ({len(result.changes)}):[/dim]")
                    for change in result.changes:
                        console.print(f"[dim]  {change}[/dim]")
                else:
                    console.print("[dim][verbose] all keys already at target values[/dim]")

        if not result.dry_run and result.backup_path:
            console.print(f"\n[dim]Backup saved: {result.backup_path}[/dim]")

    # Hint: list available .lwa files
    lwa_files = lb.list_lwa_files(config)
    if lwa_files:
        sample = ", ".join(lwa_files[:8])
        ellipsis_ = " …" if len(lwa_files) > 8 else ""
        console.print(
            f"\n[dim]Available .lwa files ({len(lwa_files)} found): "
            f"{sample}{ellipsis_}[/dim]"
        )
    elif config.ledblinky_dir:
        console.print(
            "[dim]No .lwa files found in ledblinky_dir — "
            "check that the directory is correct.[/dim]"
        )


@ledblinky_group.group("colors")
def ledblinky_colors_group():
    """Manage named color definitions in Color-RGB.ini.

    \b
    Subcommands:
      list          Show all color definitions
      edit          Rename / recolor a color and propagate the change
      normalize     Convert hex-format Colors.ini entries to named P1_BUTTON format
      sync-players  Mirror P1 colors to P2+ based on controls.ini button layout
    """


@ledblinky_colors_group.command("list")
def ledblinky_colors_list():
    """List all named color definitions from Color-RGB.ini.

    Shows the name, native R/G/B intensity values (0-48 range as stored in
    the file), and the equivalent #RRGGBB hex code for reference.
    """
    from pathlib import Path as _Path
    from . import ledblinky as lb

    config = _cfg()
    _check_config(config)

    path = _Path(config.ledblinky_dir) / lb.COLOR_RGB_NAME
    if not path.exists():
        console.print(f"[red]{lb.COLOR_RGB_NAME} not found at {path}[/red]")
        raise SystemExit(1)

    _, entries = lb.parse_color_rgb_ini(path)

    tbl = Table(box=box.SIMPLE, show_header=True)
    tbl.add_column("Name", style="cyan", no_wrap=True)
    tbl.add_column("R (0-48)", justify="right")
    tbl.add_column("G (0-48)", justify="right")
    tbl.add_column("B (0-48)", justify="right")
    tbl.add_column("Hex (#RRGGBB)")
    for e in entries:
        tbl.add_row(e.name, str(e.r), str(e.g), str(e.b), e.to_hex())

    console.print(tbl)
    console.print(f"\n[dim]{len(entries)} color definitions in {path}[/dim]")


@ledblinky_colors_group.command("edit")
@click.argument("color_name")
@click.option("--name", "new_name", default=None,
              help="New name for the color (omit to keep the existing name).")
@click.option(
    "--hex", "hex_color", default=None,
    help="New color as a RRGGBB hex string (e.g. 06BEE1). "
         "Converted from 0-255 per channel to the 0-48 intensity range for storage. "
         "Mutually exclusive with --rgb.",
)
@click.option(
    "--rgb", "rgb_values", default=None,
    help="New R,G,B values in the native 0-48 intensity range (e.g. 0,38,42). "
         "Mutually exclusive with --hex.",
)
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit changes to disk (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip .bak backups when writing in-place.")
def ledblinky_colors_edit(color_name, new_name, hex_color, rgb_values, apply_changes, no_backup):
    """Edit a color definition and propagate the rename to all LEDBlinky files.

    \b
    COLOR_NAME  current name in Color-RGB.ini (e.g. 'Blue').

    At least one of --name, --hex, or --rgb must be supplied.
    Run with just the color name to inspect its current definition.

    \b
    Three files are updated:
      1. Color-RGB.ini          — name and/or R,G,B values
      2. Colors.ini             — every value that equals COLOR_NAME exactly
      3. LEDBlinkyControls.xml  — every  color="COLOR_NAME"  attribute

    \b
    Examples:
      spindoctor ledblinky colors edit Blue              :: inspect current Blue
      spindoctor ledblinky colors edit Blue --name Turquoise --hex 06BEE1 --apply
      spindoctor ledblinky colors edit Red --rgb 48,0,12 --apply
      spindoctor ledblinky colors edit Orange --name Amber --apply
    """
    from pathlib import Path as _Path
    from . import ledblinky as lb

    config = _cfg()
    _check_config(config)

    # ── Inspect-only (no options given) ──────────────────────────────────────
    if new_name is None and hex_color is None and rgb_values is None:
        path = _Path(config.ledblinky_dir) / lb.COLOR_RGB_NAME
        if not path.exists():
            console.print(f"[red]{lb.COLOR_RGB_NAME} not found at {path}[/red]")
            raise SystemExit(1)
        _, entries = lb.parse_color_rgb_ini(path)
        for e in entries:
            if e.name == color_name:
                console.print(
                    f"[cyan]{e.name}[/cyan]  "
                    f"R={e.r}  G={e.g}  B={e.b}  ({e.to_hex()})"
                )
                return
        console.print(f"[red]Color '{color_name}' not found in {lb.COLOR_RGB_NAME}.[/red]")
        raise SystemExit(1)

    # ── Mutual exclusion ─────────────────────────────────────────────────────
    if hex_color and rgb_values:
        console.print("[red]Error: --hex and --rgb are mutually exclusive.[/red]")
        raise SystemExit(1)

    # ── Parse new RGB values ──────────────────────────────────────────────────
    new_r = new_g = new_b = None

    if hex_color:
        try:
            tmp = lb.ColorEntry.from_hex("_", hex_color)
            new_r, new_g, new_b = tmp.r, tmp.g, tmp.b
        except ValueError as exc:
            console.print(f"[red]Error:[/red] {exc}")
            raise SystemExit(1) from exc

    elif rgb_values:
        parts = [p.strip() for p in rgb_values.split(",")]
        if len(parts) != 3:
            console.print(
                "[red]Error: --rgb requires three comma-separated integers "
                "in the 0-48 range, e.g. 0,0,48.[/red]"
            )
            raise SystemExit(1)
        try:
            new_r, new_g, new_b = int(parts[0]), int(parts[1]), int(parts[2])
            if not all(0 <= v <= 48 for v in (new_r, new_g, new_b)):
                raise ValueError("all values must be in the range 0-48")
        except ValueError as exc:
            console.print(f"[red]Error: --rgb {exc}[/red]")
            raise SystemExit(1) from exc

    resolved_name = new_name if new_name is not None else color_name

    if not apply_changes:
        console.print(
            "[yellow bold][DRY RUN][/yellow bold] No files will be written. "
            "Re-run with [cyan]--apply[/cyan] to commit."
        )

    try:
        result = lb.apply_color_rename(
            config,
            old_name=color_name,
            new_name=resolved_name,
            new_r=new_r,
            new_g=new_g,
            new_b=new_b,
            dry_run=not apply_changes,
            backup=not no_backup,
        )
    except ValueError as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1) from exc

    # ── Report ────────────────────────────────────────────────────────────────
    verb = "would update" if result.dry_run else "updated"
    console.print(f"\n[blue bold]Color-RGB.ini[/blue bold]  {result.color_rgb_path}")

    if resolved_name != color_name:
        console.print(
            f"  Name: [yellow]{color_name}[/yellow] → [green]{resolved_name}[/green]"
        )
    if new_r is not None:
        preview = lb.ColorEntry("_", new_r, new_g, new_b).to_hex()
        console.print(f"  RGB: R={new_r}, G={new_g}, B={new_b}  ({preview})")

    console.print(
        f"\n  Colors.ini: "
        + (f"[green]{result.colors_ini_replacements}[/green]"
           if result.colors_ini_replacements
           else "[dim]0[/dim]")
        + f" reference(s) {verb}"
    )
    console.print(
        f"  LEDBlinkyControls.xml: "
        + (f"[green]{result.controls_xml_replacements}[/green]"
           if result.controls_xml_replacements
           else "[dim]0[/dim]")
        + f" attribute(s) {verb}"
    )

    if not result.dry_run and result.backup_paths:
        console.print(
            "\n[dim]Backups: "
            + ", ".join(str(p) for p in result.backup_paths)
            + "[/dim]"
        )


@ledblinky_colors_group.command("normalize")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip the automatic .bak backup before writing.")
@click.option("--verbose", is_flag=True,
              help="Print each section converted and the key mapping applied.")
def ledblinky_colors_normalize(apply_changes, no_backup, verbose):
    """Convert hex-format Colors.ini entries to named P1_BUTTON format.

    SpinDoctor-generated Colors.ini entries use bare hex values::

    \b
        [powerins]
        ledcolor1=FF0000      →  P1_BUTTON1=Red
        ledcolor2=FFFF00      →  P1_BUTTON2=Yellow
        joystick=FFFFFF       →  P1_JOYSTICK=White
        start=FFFFFF          →  P1_START=White
        coin=FF8000           →  P1_COIN=Orange

    The nearest match from Color-RGB.ini is chosen for each hex value.
    Sections already in named format are left completely untouched.
    Run normalize before colors edit so renames propagate to every section.
    Run normalize before colors randomize so all sections are reachable.

    \b
    Examples:
      spindoctor ledblinky colors normalize              :: preview changes
      spindoctor ledblinky colors normalize --apply      :: commit changes
      spindoctor ledblinky colors normalize --apply --verbose  :: show per-section detail
    """
    from . import ledblinky as lb

    config = _cfg()
    try:
        result = lb.normalize_colors_ini(
            config,
            dry_run=not apply_changes,
            backup=not no_backup,
        )
    except ValueError as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1)

    verb = "would convert" if result.dry_run else "converted"
    console.print(
        f"\n[blue bold]Colors.ini[/blue bold]  {result.colors_ini_path}"
    )

    if result.keys_converted == 0:
        console.print(
            "\n[dim]Nothing to normalise — all sections already use named format.[/dim]"
        )
    else:
        console.print(
            f"  {verb}: "
            f"[green]{result.sections_converted}[/green] section(s), "
            f"[green]{result.keys_converted}[/green] key(s)"
        )
        if result.dry_run:
            console.print(
                "\n[yellow]Dry-run — pass [bold]--apply[/bold] to commit.[/yellow]"
            )
        elif result.backup_path:
            console.print(f"\n[dim]Backup: {result.backup_path}[/dim]")

    if verbose and result.converted_details:
        _VERBOSE_SAMPLE = 50
        shown = result.converted_details[:_VERBOSE_SAMPLE]
        console.print(
            f"\n[dim][verbose] first {len(shown)} converted sections "
            f"(of {result.sections_converted}):[/dim]"
        )
        for sec_name, key_changes in shown:
            console.print(f"[dim]  [{sec_name}][/dim]")
            for old_k, new_k, color in key_changes:
                console.print(f"[dim]    {old_k} → {new_k}={color}[/dim]")
        if len(result.converted_details) > _VERBOSE_SAMPLE:
            console.print(
                f"[dim]  … {len(result.converted_details) - _VERBOSE_SAMPLE} more sections[/dim]"
            )


@ledblinky_colors_group.command("brightness")
@click.option("--scale", "scale_pct", required=True, type=float,
              metavar="PCT",
              help="Target brightness level (0–100).  "
                   "100 = maximum brightness (all colors normalized to full intensity). "
                   "50 = half brightness.  10 = near-dark night mode.  0 = all off.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip the automatic .bak backup before writing.")
@click.option("--verbose", is_flag=True, help="Print the Color-RGB.ini path and color count scaled.")
def ledblinky_colors_brightness(scale_pct, apply_changes, no_backup, verbose):
    """Set all Color-RGB.ini colors to a uniform brightness level.

    Each color is first normalized to its maximum possible intensity (dominant
    channel → 48), then scaled by SCALE_PCT/100.  This guarantees every button
    — P1, P2, admin, Start — is at the same brightness regardless of how it
    was previously stored.

    \b
    Examples:
      spindoctor ledblinky colors brightness --scale 100 --apply   :: maximum brightness
      spindoctor ledblinky colors brightness --scale 50  --apply   :: half brightness
      spindoctor ledblinky colors brightness --scale 10  --apply   :: night mode
      spindoctor ledblinky colors brightness --scale 75           :: preview 75%
    """
    from . import ledblinky as lb

    if not (0.0 <= scale_pct <= 100.0):
        console.print("[red]Error:[/red] --scale must be between 0 and 100.")
        raise SystemExit(1)

    config = _cfg()
    try:
        result = lb.scale_colors_brightness(
            config,
            scale_pct=scale_pct,
            dry_run=not apply_changes,
            backup=not no_backup,
        )
    except ValueError as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1)

    verb = "would scale" if result.dry_run else "scaled"
    console.print(
        f"\n[blue bold]Color-RGB.ini[/blue bold]  {result.color_rgb_path}"
    )
    console.print(
        f"  {verb}: [green]{result.colors_scaled}[/green] color(s) "
        f"at [cyan]{scale_pct:.0f}%[/cyan] brightness"
    )
    if result.dry_run:
        console.print(
            "\n[yellow]Dry-run — pass [bold]--apply[/bold] to commit.[/yellow]"
        )
    elif result.backup_path:
        console.print(f"\n[dim]Backup: {result.backup_path}[/dim]")
    if verbose:
        console.print(f"\n[dim][verbose] Color-RGB.ini: {result.color_rgb_path}[/dim]")
        if result.color_changes:
            console.print(f"[dim][verbose] per-color changes at {scale_pct:.0f}%:[/dim]")
            for name, or_, og, ob, nr, ng, nb in result.color_changes:
                old_hex = f"#{round(or_/48*255):02X}{round(og/48*255):02X}{round(ob/48*255):02X}"
                new_hex = f"#{round(nr/48*255):02X}{round(ng/48*255):02X}{round(nb/48*255):02X}"
                changed = "→" if (or_, og, ob) != (nr, ng, nb) else "="
                console.print(
                    f"[dim]  {name:<20s}  {or_:2d},{og:2d},{ob:2d} ({old_hex})  "
                    f"{changed}  {nr:2d},{ng:2d},{nb:2d} ({new_hex})[/dim]"
                )


@ledblinky_colors_group.command("randomize")
@click.option("--seed", type=int, default=None,
              help="Integer seed for reproducible output.  "
                   "Omit for a fresh random shuffle every run.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip the automatic .bak backup before writing.")
@click.option("--verbose", is_flag=True,
              help="Print the Colors.ini path, palette size, and sections updated.")
def ledblinky_colors_randomize(seed, apply_changes, no_backup, verbose):
    """Give each game its own random button colors.

    For every section in Colors.ini that has player-button keys:

    \b
      - All P*_BUTTON* and P*_JOYSTICK keys → one random color (same for all
        players, so every button on a game glows the same shade).
      - All P*_COIN and P*_START keys → a second independently-drawn random
        color (the accent color for the meta-buttons).
      - Each game gets its own independent draw — the cabinet looks varied.
      - Only EXISTING keys are updated.  New button lines are never added,
        so buttons intentionally left dark (absent from the section) stay dark.
      - Black / off colors (all-zero channels) are excluded from the pool.

    \b
    Examples:
      spindoctor ledblinky colors randomize               :: preview
      spindoctor ledblinky colors randomize --apply       :: commit
      spindoctor ledblinky colors randomize --seed 42 --apply  :: reproducible
    """
    from . import ledblinky as lb

    config = _cfg()
    try:
        result = lb.randomize_entry_colors(
            config,
            dry_run=not apply_changes,
            backup=not no_backup,
            seed=seed,
        )
    except ValueError as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1)

    verb = "would update" if result.dry_run else "updated"
    console.print(
        f"\n[blue bold]Colors.ini[/blue bold]  {result.colors_ini_path}"
    )
    console.print(
        f"  Palette size   : [cyan]{result.palette_size}[/cyan] non-black colors"
    )
    console.print(
        f"  Sections {verb:13s}: [green]{result.sections_updated}[/green]"
    )
    if result.sections_skipped_old_format:
        console.print(
            f"  [yellow]Sections skipped (old format): "
            f"{result.sections_skipped_old_format}[/yellow]"
        )
        console.print(
            "  [yellow]→ These use ledcolor1=/joystick=/start=/coin= hex keys.[/yellow]"
        )
        console.print(
            "  [yellow]→ Run [bold]spindoctor ledblinky colors normalize --apply[/bold] "
            "first, then re-run randomize.[/yellow]"
        )
    if result.sections_skipped:
        console.print(
            f"  Sections skipped (empty)  : [dim]{result.sections_skipped}[/dim] "
            f"(no player keys or ledcolor keys — left unchanged)"
        )
    if result.seed is not None:
        console.print(f"  Seed             : [dim]{result.seed}[/dim]")
    if result.dry_run and result.sections_updated:
        console.print(
            "\n[yellow]Dry-run — pass [bold]--apply[/bold] to commit.[/yellow]"
        )
    elif result.backup_path:
        console.print(f"\n[dim]Backup: {result.backup_path}[/dim]")
    if verbose:
        console.print(f"\n[dim][verbose] Colors.ini: {result.colors_ini_path}[/dim]")
        console.print(
            f"[dim][verbose] palette={result.palette_size} colors  "
            f"updated={result.sections_updated}  "
            f"skipped_old_fmt={result.sections_skipped_old_format}  "
            f"skipped_empty={result.sections_skipped}[/dim]"
        )
        if result.updated_details:
            _VERBOSE_SAMPLE = 50
            shown = result.updated_details[:_VERBOSE_SAMPLE]
            console.print(
                f"[dim][verbose] first {len(shown)} updated sections "
                f"(of {result.sections_updated}):[/dim]"
            )
            for sec_name, btn_color, cs_color in shown:
                console.print(
                    f"[dim]  {sec_name:<30s}  buttons={btn_color}  coin/start={cs_color}[/dim]"
                )
            if len(result.updated_details) > _VERBOSE_SAMPLE:
                console.print(
                    f"[dim]  … {len(result.updated_details) - _VERBOSE_SAMPLE} more[/dim]"
                )


@ledblinky_colors_group.command("sync-players")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip the automatic .bak backup before writing.")
@click.option("--override", is_flag=True,
              help="Replace existing P2+ color entries with the current P1-mirrored "
                   "color. Without this flag, existing entries are never changed.")
@click.option("--verbose", is_flag=True,
              help="Print every key added (or replaced) per ROM.")
def ledblinky_colors_sync_players(apply_changes, no_backup, override, verbose):
    """Mirror P1 colors to all additional players based on controls.ini.

    ``ledblinky generate`` writes Colors.ini sections with P1 keys only.
    When a game has multiple players (P2, P3, P4, …), those buttons have no
    color entry and fall back to the XML default color instead of the per-game
    palette you configured.

    This command closes that gap: for every ROM that has both a Colors.ini
    section and a controls.ini entry, it adds any missing P{n}_KEY entries
    (where n >= 2) by mirroring the matching P1 color.  Works for any number
    of additional players — P2, P3, P4, and beyond.

    \b
    Rules:
      - Only adds keys that are listed in controls.ini (no invented buttons).
      - Only mirrors from P1 — if P1_KEY is absent, that key is skipped.
      - Never overwrites existing Colors.ini keys unless --override is passed.
      - ROMs with no controls.ini entry are left unchanged.
      - P1 keys are never modified regardless of --override.

    \b
    Examples:
      spindoctor ledblinky colors sync-players                       :: preview
      spindoctor ledblinky colors sync-players --apply               :: commit
      spindoctor ledblinky colors sync-players --apply --verbose
      spindoctor ledblinky colors sync-players --apply --override    :: replace existing P2+ entries
    """
    from . import ledblinky as lb

    config = _cfg()
    try:
        result = lb.sync_player_colors(
            config,
            dry_run=not apply_changes,
            backup=not no_backup,
            override=override,
        )
    except (ValueError, FileNotFoundError) as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1)

    console.print(
        f"\n[blue bold]Colors.ini[/blue bold]  {result.colors_ini_path}"
    )
    verb = "would update" if result.dry_run else "updated"
    keys_detail = f"[cyan]{result.keys_added}[/cyan] added"
    if result.keys_overwritten:
        keys_detail += f", [yellow]{result.keys_overwritten}[/yellow] replaced"
    console.print(f"  ROMs {verb:16s}: [green]{result.roms_updated}[/green]"
                  f"  ({keys_detail})")
    console.print(
        f"  ROMs skipped (already complete) : [dim]{result.roms_skipped_complete}[/dim]"
    )
    console.print(
        f"  ROMs skipped (no controls.ini)  : [dim]{result.roms_skipped_no_controls}[/dim]"
    )

    if verbose and result.details:
        _SAMPLE = 50
        shown = result.details[:_SAMPLE]
        console.print(
            f"\n[dim][verbose] first {len(shown)} updated ROMs "
            f"(of {result.roms_updated}):[/dim]"
        )
        for rom_name, keys in shown:
            console.print(f"[dim]  {rom_name:<30s}  added/replaced: {', '.join(keys)}[/dim]")
        if len(result.details) > _SAMPLE:
            console.print(f"[dim]  … {len(result.details) - _SAMPLE} more[/dim]")

    if result.dry_run and result.roms_updated:
        console.print(
            "\n[yellow]Dry-run — pass [bold]--apply[/bold] to commit.[/yellow]"
        )
    elif result.backup_path:
        console.print(f"\n[dim]Backup: {result.backup_path}[/dim]")


@ledblinky_group.command("fill-defaults")
@click.option("--color", "default_color", default="White", show_default=True,
              help="Named color from Color-RGB.ini for player buttons. "
                   "Must exist in Color-RGB.ini.")
@click.option("--buttons", "n_buttons", default=6, show_default=True, type=int,
              help="Number of P{n}_BUTTON entries per player (clamped 1-8).")
@click.option("--players", "n_players", default=1, show_default=True,
              type=click.IntRange(1, 4),
              help="Number of player blocks to generate (P1–P4).  "
                   "All players get the same color (mirrored).")
@click.option("--admin-buttons", "admin_buttons", default=0, show_default=True,
              type=int,
              help="Extra admin/cabinet buttons to add on the next player slot "
                   "(P{players+1}).  0 disables the admin block.")
@click.option("--admin-color", "admin_color", default="White", show_default=True,
              help="Named color for the admin button block.")
@click.option("--override-uniform", is_flag=True,
              help="Also update existing sections where ALL button colors are "
                   "the same value.  Mixed-color sections are never touched.")
@click.option("--no-add-keys", is_flag=True,
              help="When overriding, only replace values of keys already "
                   "present — do not insert new P*_BUTTON/JOYSTICK/START/COIN "
                   "keys.  Only meaningful with --override-uniform.")
@click.option("--system", default=None, metavar="SYSTEM",
              help="Process only this HyperSpin system.  Default: all systems "
                   "(including Favorites / Recently Played / Most Played).")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip the automatic .bak backup before writing.")
@click.option("--verbose", is_flag=True, help="Print the Colors.ini path and add/override/skip counts.")
def ledblinky_fill_defaults(
    default_color, n_buttons, n_players, admin_buttons, admin_color,
    override_uniform, no_add_keys, system, apply_changes, no_backup, verbose,
):
    """Add default Colors.ini entries for ROMs with no LED mapping.

    When a ROM has no entry in Colors.ini, LedBlinky treats all of its buttons
    as inactive and turns them off (black).  Use this command to append a
    uniform default entry for every ROM that is not already covered, so
    unmapped buttons glow a steady color instead of going dark.

    With --players 2 --buttons 8 each generated entry looks like::

    \b
        [rom_name]
        P1_BUTTON1=White  ...  P1_BUTTON8=White
        P1_JOYSTICK=White  P1_START=White  P1_COIN=White
        P2_BUTTON1=White  ...  P2_BUTTON8=White
        P2_JOYSTICK=White  P2_START=White  P2_COIN=White

    Add --admin-buttons 6 --admin-color Green for cabinet-level buttons::

    \b
        P3_BUTTON1=Green  ...  P3_BUTTON6=Green
        P3_COIN=Green  P3_START=Green

    By default only ROMs with no existing section are touched.  Pass
    --override-uniform to also update existing entries where all button colors
    are identical (e.g. all White), replacing them with the new --color.
    Sections with mixed colors (e.g. one Red button, one Blue button) are
    never modified regardless of flags.

    Use --no-add-keys with --override-uniform to preserve the exact set of
    keys already in the section — only the color VALUES are replaced, and no
    new P*_BUTTON entries are inserted.

    Synthetic wheels (Favorites, Recently Played, Most Played) are included
    so games that appear only in those wheels are also covered.

    \b
    Examples:
      spindoctor ledblinky fill-defaults                              :: preview
      spindoctor ledblinky fill-defaults --apply                      :: commit
      spindoctor ledblinky fill-defaults --players 2 --buttons 8 --apply
      spindoctor ledblinky fill-defaults --players 2 --admin-buttons 6 --admin-color Green --apply
      spindoctor ledblinky fill-defaults --system "MAME"              :: one system
      spindoctor ledblinky fill-defaults --color Purple --apply
      spindoctor ledblinky fill-defaults --color White --override-uniform --apply
      spindoctor ledblinky fill-defaults --color White --override-uniform --no-add-keys --apply
    """
    from . import ledblinky as lb

    config = _cfg()
    try:
        result = lb.fill_default_colors(
            config,
            default_color=default_color,
            n_buttons=n_buttons,
            n_players=n_players,
            admin_buttons=admin_buttons,
            admin_color=admin_color,
            override_uniform=override_uniform,
            no_add_keys=no_add_keys,
            system=system,
            dry_run=not apply_changes,
            backup=not no_backup,
        )
    except ValueError as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1)

    verb_add = "would add" if result.dry_run else "added"
    verb_ovr = "would update" if result.dry_run else "updated"
    console.print(
        f"\n[blue bold]Colors.ini[/blue bold]  {result.colors_ini_path}"
    )
    console.print(
        f"  ROMs checked   : [cyan]{result.roms_checked}[/cyan]"
    )

    players_desc = (
        f"players=[cyan]{n_players}[/cyan], " if n_players > 1 else ""
    )
    admin_desc = (
        f", admin=[cyan]{admin_buttons}×{admin_color}[/cyan]"
        if admin_buttons > 0 else ""
    )
    color_desc = (
        f"({players_desc}color=[cyan]{default_color}[/cyan], "
        f"buttons=[cyan]{n_buttons}[/cyan]{admin_desc})"
    )

    if result.roms_added:
        console.print(
            f"  {verb_add:12s} : [green]{result.roms_added}[/green] "
            f"new entr{'y' if result.roms_added == 1 else 'ies'} {color_desc}"
        )
    if result.roms_overridden:
        no_keys_note = " [no new keys]" if no_add_keys else ""
        console.print(
            f"  {verb_ovr:12s} : [green]{result.roms_overridden}[/green] "
            f"uniform entr{'y' if result.roms_overridden == 1 else 'ies'} "
            f"→ [cyan]{default_color}[/cyan]{no_keys_note}"
        )
    if result.roms_skipped_mixed:
        console.print(
            f"  skipped mixed  : [yellow]{result.roms_skipped_mixed}[/yellow] "
            f"entr{'y' if result.roms_skipped_mixed == 1 else 'ies'} "
            f"(mixed colors — not overridden)"
        )
    if result.roms_added == 0 and result.roms_overridden == 0:
        console.print(
            "\n[dim]Nothing to change — every ROM already has a Colors.ini entry.[/dim]"
        )
        if override_uniform and result.roms_skipped_mixed:
            console.print(
                "[dim]  (some entries have mixed colors and were intentionally skipped)[/dim]"
            )

    if result.dry_run and (result.roms_added or result.roms_overridden):
        console.print(
            "\n[yellow]Dry-run — pass [bold]--apply[/bold] to commit.[/yellow]"
        )
    elif result.backup_path:
        console.print(f"\n[dim]Backup: {result.backup_path}[/dim]")
    if verbose:
        console.print(f"\n[dim][verbose] Colors.ini: {result.colors_ini_path}[/dim]")
        if result.added_rom_names:
            console.print(f"[dim][verbose] added ({len(result.added_rom_names)}):[/dim]")
            for name in result.added_rom_names:
                console.print(f"[dim]  + {name}[/dim]")
        if result.overridden_rom_names:
            console.print(f"[dim][verbose] overridden ({len(result.overridden_rom_names)}):[/dim]")
            for name in result.overridden_rom_names:
                console.print(f"[dim]  ~ {name}[/dim]")
        if result.roms_skipped_mixed:
            console.print(
                f"[dim][verbose] skipped mixed: {result.roms_skipped_mixed} "
                f"(hand-crafted entries left untouched)[/dim]"
            )


# ─── ledblinky admin-buttons ──────────────────────────────────────────────────

@ledblinky_group.group("admin-buttons")
def ledblinky_admin_buttons_group():
    """Manage cabinet-level (admin) button colors across all Colors.ini entries.

    \b
    Subcommands:
      set   Write per-button admin colors to every ROM section in Colors.ini
    """


@ledblinky_admin_buttons_group.command("set")
@click.option("--player", "admin_player", default=3, show_default=True,
              type=click.IntRange(1, 6),
              help="Player slot for the admin/cabinet buttons "
                   "(P1–P6).  Use P{players+1} of your cabinet — e.g. 3 "
                   "for a 2-player cabinet.")
@click.option("--colors", "colors_csv", default=None, metavar="C1,C2,...",
              help="Comma-separated list of color names, one per button "
                   "(e.g. 'Red,Blue,Green,White,White,Yellow').  "
                   "Determines how many button keys are written.  "
                   "Use --colors OR --color+--count, not both.")
@click.option("--color", "uniform_color", default=None, metavar="COLOR",
              help="Single color applied to all admin buttons (combine with --count).")
@click.option("--count", "button_count", default=6, show_default=True, type=int,
              help="Number of buttons when using --color (ignored with --colors).")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--no-backup", is_flag=True,
              help="Skip the automatic .bak backup before writing.")
@click.option("--verbose", is_flag=True, help="Print the Colors.ini path and sections updated.")
def ledblinky_admin_buttons_set(
    admin_player, colors_csv, uniform_color, button_count, apply_changes, no_backup, verbose,
):
    """Set individual admin/cabinet button colors across ALL Colors.ini sections.

    This command walks every ROM section in ``Colors.ini`` and writes
    (or overwrites) the ``P{player}_BUTTON*`` keys for the admin/cabinet
    player slot so that those buttons always display the specified colors
    regardless of which game is currently running.

    \b
    Color list form — one color per button:
      spindoctor ledblinky admin-buttons set \\
          --colors "Red,Blue,Green,White,White,Yellow" --apply

    \b
    Uniform form — same color on every button:
      spindoctor ledblinky admin-buttons set --color Green --count 6 --apply

    \b
    Specify player slot explicitly (default is 3 for a 2-player cabinet):
      spindoctor ledblinky admin-buttons set --player 3 \\
          --colors "Red,Blue,Green,White,White,Yellow" --apply

    \b
    Dry-run preview (default — no files written):
      spindoctor ledblinky admin-buttons set --colors "Red,Blue,Green,White,White,Yellow"
    """
    from . import ledblinky as lb

    # Resolve button_colors list
    if colors_csv and uniform_color:
        console.print(
            "[red]Error:[/red] Use --colors OR --color+--count, not both."
        )
        raise SystemExit(1)
    if colors_csv:
        button_colors = [c.strip() for c in colors_csv.split(",") if c.strip()]
        if not button_colors:
            console.print("[red]Error:[/red] --colors list is empty.")
            raise SystemExit(1)
    elif uniform_color:
        button_count = max(1, button_count)
        button_colors = [uniform_color] * button_count
    else:
        console.print(
            "[red]Error:[/red] Provide --colors 'C1,C2,...' or --color COLOR [--count N]."
        )
        raise SystemExit(1)

    config = _cfg()
    if not apply_changes:
        console.print(
            "[yellow bold][DRY RUN][/yellow bold] No files will be written. "
            "Re-run with [cyan]--apply[/cyan] to commit."
        )
    try:
        result = lb.patch_admin_button_colors(
            config,
            button_colors=button_colors,
            admin_player=admin_player,
            dry_run=not apply_changes,
            backup=not no_backup,
        )
    except ValueError as exc:
        console.print(f"[red]Error:[/red] {exc}")
        raise SystemExit(1)

    colors_display = ", ".join(
        f"[cyan]{c}[/cyan]" for c in result.button_colors
    )
    verb = "would update" if result.dry_run else "updated"
    console.print(
        f"\n[blue bold]Colors.ini[/blue bold]  {result.colors_ini_path}"
    )
    console.print(
        f"  Admin slot   : [cyan]P{result.admin_player}[/cyan]"
    )
    console.print(
        f"  Button colors: {colors_display}"
    )
    if result.sections_updated == 0:
        console.print(
            "\n[dim]Nothing to update — all sections already have these colors.[/dim]"
        )
    else:
        console.print(
            f"  {verb}      : [green]{result.sections_updated}[/green] "
            f"section{'s' if result.sections_updated != 1 else ''}"
        )
        if result.dry_run:
            console.print(
                "\n[yellow]Dry-run — pass [bold]--apply[/bold] to commit.[/yellow]"
            )
        elif result.backup_path:
            console.print(f"\n[dim]Backup: {result.backup_path}[/dim]")
    if verbose:
        console.print(f"\n[dim][verbose] Colors.ini: {result.colors_ini_path}[/dim]")
        if result.updated_section_names:
            console.print(
                f"[dim][verbose] sections updated ({len(result.updated_section_names)}, "
                f"player=P{result.admin_player}):[/dim]"
            )
            for name in result.updated_section_names:
                console.print(f"[dim]  ~ {name}[/dim]")
        else:
            console.print(f"[dim][verbose] no sections updated (player=P{result.admin_player})[/dim]")


# ─── add-system ───────────────────────────────────────────────────────────────

# HyperSpin Main Menu media slots that we know how to fetch from ScreenScraper.
SYSTEM_MEDIA_SLOTS = ("wheel", "background", "video")


@cli.command("add-system")
@click.argument("system_name")
@click.option("--no-menu", is_flag=True, help="Skip the Main Menu upsert step.")
@click.option("--no-system-media", is_flag=True,
              help="Skip downloading wheel/background/video for the new system.")
@click.option("--no-db", is_flag=True,
              help="Skip building the per-system database from ROMs.")
@click.option("--no-game-media", is_flag=True,
              help="Skip per-game media fetch for the new system.")
@click.option("--pick-media", "pick_media", is_flag=True,
              help="Interactively preview & pick when a slot has multiple candidates.")
@click.option("--source", default=None, type=click.Choice(["screenscraper", "thegamesdb"]))
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--output-dir", type=click.Path(), default=None)
def add_system(system_name, no_menu, no_system_media, no_db, no_game_media,
               pick_media, source, apply_changes, output_dir):
    """Bootstrap a top-level console end-to-end (e.g. PS3, Dreamcast).

    Scaffolds the ROM/database folders, adds the Main Menu entry, downloads
    wheel/background/video for the system tile, builds the games database
    from the ROMs you've already placed in <roms_dir>/<SYSTEM>/, and runs
    per-game media fetch for the new system.

    \b
    Examples:
      spindoctor add-system "Sony Playstation 3"           # dry-run preview
      spindoctor add-system "Sony Playstation 3" --apply   # commit
      spindoctor add-system Dreamcast --pick-media --apply
      spindoctor add-system PS3 --no-game-media --apply
    """
    from .audit import build_stub_entry, scan_roms
    from .media import MediaDownloader
    from .rocketlauncher import upsert_main_menu_system
    from .scraper import MetadataError, build_client

    config = _cfg()
    _check_config(config)

    out_base = Path(output_dir) if output_dir else None

    if not apply_changes:
        console.print(
            "[yellow bold][DRY RUN][/yellow bold] No files will be written. "
            "Re-run with [cyan]--apply[/cyan] to commit."
        )

    console.print(Panel(f" add-system: {system_name} ", style="bold blue"))

    # 1. Scaffold folders ──────────────────────────────────────────────────────
    rom_dir = Path(config.roms_dir) / system_name
    db_dir = config.databases_dir / system_name

    console.print("[blue bold]1. Scaffold folders[/blue bold]")
    for d in (rom_dir, db_dir):
        if d.exists():
            console.print(f"  [dim]exists:[/dim] {d}")
        elif not apply_changes:
            console.print(f"  [yellow]would create:[/yellow] {d}")
        else:
            d.mkdir(parents=True, exist_ok=True)
            console.print(f"  [green]+[/green] {d}")

    # 2. Main Menu upsert ──────────────────────────────────────────────────────
    if no_menu:
        console.print("[dim]2. Main Menu upsert — skipped.[/dim]")
    else:
        console.print("\n[blue bold]2. Main Menu upsert[/blue bold]")
        if not apply_changes:
            console.print(f"  [yellow]would add[/yellow] '{system_name}' to "
                          f"{config.databases_dir / 'Main Menu' / 'Main Menu.xml'}")
        else:
            path, added = upsert_main_menu_system(system_name, config, out_base)
            if added:
                console.print(f"  [green]+[/green] added to {path}")
            else:
                console.print(f"  [dim]already present in {path}[/dim]")

    # 3. System-level media ────────────────────────────────────────────────────
    if no_system_media:
        console.print("[dim]3. System-level media — skipped.[/dim]")
    else:
        console.print("\n[blue bold]3. System-level media[/blue bold]")
        try:
            client = build_client(config, source)
        except MetadataError as e:
            err_console.print(f"  [red]{e}[/red]")
            client = None

        if client is None or not hasattr(client, "fetch_system_media"):
            console.print(
                "  [yellow]System media fetch requires ScreenScraper.[/yellow]"
            )
        else:
            try:
                slots = client.fetch_system_media(system_name)
            except MetadataError as e:
                err_console.print(f"  [red]{e}[/red]")
                slots = {}

            if not slots:
                console.print(f"  [yellow]No system media available for {system_name}.[/yellow]")
            else:
                downloader = MediaDownloader(config, output_dir_override=out_base)
                for slot in SYSTEM_MEDIA_SLOTS:
                    cands = slots.get(slot, [])
                    if not cands:
                        console.print(f"  [dim]{slot}:[/dim] none")
                        continue
                    dest = downloader.system_media_path(system_name, slot)
                    if not apply_changes:
                        console.print(
                            f"  [yellow]would fetch[/yellow] {slot}  "
                            f"({len(cands)} candidate(s)) → {dest}"
                        )
                        continue
                    if pick_media and len(cands) > 1:
                        r = downloader.download_with_picker(
                            system_name, system_name, slot, cands, dest,
                            interactive=True,
                        )
                    else:
                        r = downloader.download_to_path(
                            dest, cands[0].url,
                            label=system_name, media_type=slot,
                        )
                    _print_dl_result(slot, r)

    # 4. Build the games database ──────────────────────────────────────────────
    if no_db:
        console.print("[dim]4. Games database — skipped.[/dim]")
    else:
        console.print("\n[blue bold]4. Games database[/blue bold]")
        roms = scan_roms(system_name, Path(config.roms_dir))
        if not roms:
            console.print(f"  [yellow]No ROMs found in {rom_dir} — drop ROMs in and re-run.[/yellow]")
        else:
            db = load_database(system_name, config.databases_dir)
            existing = set(db.games().keys())
            new_count = 0
            for rom_name in sorted(roms):
                if rom_name in existing:
                    continue
                stub = build_stub_entry(
                    rom_name,
                    strip_variants=config.strip_variant_tags_in_display_name,
                )
                if not apply_changes:
                    console.print(f"  [yellow]+[/yellow] would add stub: {rom_name}")
                else:
                    db.upsert_game(stub)
                new_count += 1
            if apply_changes and new_count:
                _tmp = config.effective_atomic_tmp_dir
                if out_base:
                    saved = db.save(
                        output_path=out_base / "Databases" / system_name / f"{system_name}.xml",
                        backup=False, tmp_dir=_tmp,
                    )
                else:
                    _bak_dir = Path(config.backup_dir) if getattr(config, "backup_dir", "") else None
                    saved = db.save(backup=config.backup_before_modify,
                                    backup_dir=_bak_dir, tmp_dir=_tmp)
                console.print(f"  [green]+[/green] {new_count} stub(s) → {saved}")
            elif new_count:
                console.print(f"  [yellow]would add {new_count} stub(s)[/yellow]")
            else:
                console.print("  [green]Database already in sync with ROMs.[/green]")

    # 5. Per-game media fetch ──────────────────────────────────────────────────
    if no_game_media:
        console.print("[dim]5. Per-game media — skipped.[/dim]")
        return
    console.print("\n[blue bold]5. Per-game media[/blue bold]")
    extra = ["--system", system_name]
    if pick_media:
        extra.append("--pick-media")
    if apply_changes:
        extra.append("--apply")
    if output_dir:
        extra.extend(["--output-dir", str(output_dir)])
    if source:
        extra.extend(["--source", source])
    console.print(f"  [dim]running:[/dim] spindoctor fetch-media {' '.join(extra)}")
    try:
        cli.main(args=["fetch-media", *extra], standalone_mode=False, prog_name="spindoctor")
    except SystemExit:
        pass


def _print_dl_result(slot: str, r) -> None:
    if r.skipped and r.success:
        console.print(f"  [dim]·[/dim] {slot}: already present at {r.path}")
    elif r.skipped:
        console.print(f"  [yellow]·[/yellow] {slot}: skipped ({r.error})")
    elif r.success:
        console.print(f"  [green]+[/green] {slot}: {r.path}")
    else:
        console.print(f"  [red]✗[/red] {slot}: {r.error}")


# ─── add-pc-system / pc-rename ────────────────────────────────────────────────

# Default overrides for a brand-new PC/Windows/Steam library.  Writes
# settings.json so every other code path (audit, scraper, organize,
# rocketlauncher) immediately treats the system like a PC library.
PC_DEFAULT_OVERRIDES: dict = {
    "rom_extensions": [".exe", ".lnk", ".url", ".bat"],
    "layout": "flat",
    "emulator": "PCLauncher",
    "recursive_scan": True,
    "title_strategy": "smart",
}


def _ensure_pc_overrides(config: Config, system_name: str) -> dict:
    """Merge PC defaults into ``system_overrides[system_name]`` (preserves
    existing user-set keys) and persist.  Returns the merged entry."""
    overrides = dict(config.system_overrides)
    entry = dict(overrides.get(system_name, {}))
    for k, v in PC_DEFAULT_OVERRIDES.items():
        entry.setdefault(k, v)
    overrides[system_name] = entry
    config.system_overrides = overrides
    save_config(config)
    return entry


def _propose_pc_titles(
    system_name: str,
    config: Config,
) -> list[tuple[Path, str]]:
    """Walk the system's ROM dir and return ``(path, proposed_title)`` pairs.

    Honours the override's title_strategy.  Same files that ``scan_roms``
    would pick up — kept separate so the picker can show the file path
    behind each proposed title.
    """
    from .config import get_rom_extensions, get_system_overrides
    from .romutils import derive_pc_title

    rom_dir = Path(config.roms_dir) / system_name
    if not rom_dir.exists():
        return []
    extensions = {e.lower() for e in get_rom_extensions(system_name)}
    strategy = (
        get_system_overrides().get(system_name, {}).get("title_strategy", "smart")
    )
    proposals: list[tuple[Path, str]] = []
    for path in sorted(rom_dir.rglob("*")):
        if not path.is_file() or path.suffix.lower() not in extensions:
            continue
        proposals.append((path, derive_pc_title(path, rom_dir, strategy)))
    return proposals


@cli.command("add-pc-system")
@click.argument("system_name", required=False, default="PC Games")
@click.option("--rename/--no-rename", "rename", default=True,
              help="Interactively confirm/edit derived titles before writing the DB.")
@click.option("--no-interactive", is_flag=True,
              help=("Auto-accept every proposed title without prompting. "
                    "Use from non-TTY contexts (GUI subprocesses, cron, "
                    "CI) — the interactive review path calls input() "
                    "and blocks on stdin otherwise."))
@click.option("--no-menu", is_flag=True, help="Skip the Main Menu upsert step.")
@click.option("--no-system-media", is_flag=True,
              help="Skip downloading wheel/background/video for the new system.")
@click.option("--no-db", is_flag=True, help="Skip building the per-system database.")
@click.option("--no-game-media", is_flag=True, help="Skip per-game media fetch.")
@click.option("--no-pclauncher", is_flag=True,
              help="Skip generating per-game PCLauncher INIs.")
@click.option("--overwrite-pclauncher", is_flag=True,
              help="Overwrite existing PCLauncher INIs (default: keep user edits).")
@click.option("--pick-media", "pick_media", is_flag=True,
              help="Interactively preview & pick when a media slot has multiple candidates.")
@click.option("--source", default=None, type=click.Choice(["screenscraper", "thegamesdb"]))
@click.option("--apply", "apply_changes", is_flag=True,
              help="Commit writes (default: dry-run preview).")
@click.option("--output-dir", type=click.Path(), default=None)
def add_pc_system(system_name, rename, no_interactive, no_menu, no_system_media,
                  no_db, no_game_media, no_pclauncher, overwrite_pclauncher,
                  pick_media, source, apply_changes, output_dir):
    """Bootstrap a PC/Windows/Steam games system end-to-end.

    \b
    Equivalent to ``add-system`` with PC-friendly defaults baked in:
      • recursive directory scan (your install layout is preserved)
      • smart title extraction (parent folder for nested .exe; stem for .lnk/.url)
      • PCLauncher emulator wired through RocketLauncher
      • per-game PCLauncher INIs generated mapping each title → executable

    \b
    Examples:
      spindoctor add-pc-system                                       # dry-run preview
      spindoctor add-pc-system --apply                               # commit
      spindoctor add-pc-system "Windows Games" --pick-media --apply
      spindoctor add-pc-system "Steam Games" --no-rename --no-pclauncher --apply
    """
    from .config import reset_override_cache

    config = _cfg()
    _check_config(config)

    out_base = Path(output_dir) if output_dir else None

    # 1. Stamp PC overrides ───────────────────────────────────────────────────
    if not apply_changes:
        console.print(
            "[yellow bold][DRY RUN][/yellow bold] No files will be written, "
            "and overrides will not be persisted. "
            "Re-run with [cyan]--apply[/cyan] to commit."
        )
    console.print(Panel(f" add-pc-system: {system_name} ", style="bold magenta"))
    console.print("[blue bold]0. PC system overrides[/blue bold]")
    if not apply_changes:
        merged = {**PC_DEFAULT_OVERRIDES, **config.system_overrides.get(system_name, {})}
        console.print(f"  [yellow]would write[/yellow] system_overrides[{system_name!r}]:")
        for k, v in merged.items():
            console.print(f"    [dim]{k}:[/dim] {v}")
    else:
        entry = _ensure_pc_overrides(config, system_name)
        reset_override_cache()
        console.print(f"  [green]+[/green] saved override for [cyan]{system_name}[/cyan]")
        for k, v in entry.items():
            console.print(f"    [dim]{k}:[/dim] {v}")

    # 2. Run the standard add-system flow.  We always pass --no-db and
    #    --no-game-media because PC systems need the title-review step to
    #    happen between scan and DB write, and per-game media fetch must
    #    follow the DB build (otherwise there are no game names to scrape).
    inner = ["add-system", system_name, "--no-db", "--no-game-media"]
    if no_menu:
        inner.append("--no-menu")
    if no_system_media:
        inner.append("--no-system-media")
    if pick_media:
        inner.append("--pick-media")
    if apply_changes:
        inner.append("--apply")
    if output_dir:
        inner.extend(["--output-dir", str(output_dir)])
    if source:
        inner.extend(["--source", source])

    console.print(f"\n[dim]running:[/dim] spindoctor {' '.join(inner)}")
    try:
        cli.main(args=inner, standalone_mode=False, prog_name="spindoctor")
    except SystemExit:
        pass

    if no_db:
        console.print("[dim]4. Games database — skipped.[/dim]")
        if not no_pclauncher:
            console.print(
                "[yellow]Skipping PCLauncher INI generation because --no-db was passed.[/yellow]"
            )
        return

    # 3. Title review + DB build ─────────────────────────────────────────────
    console.print("\n[blue bold]4. Title review + games database[/blue bold]")
    proposals = _propose_pc_titles(system_name, config)
    if not proposals:
        rom_dir = Path(config.roms_dir) / system_name
        console.print(
            f"  [yellow]No game files found under {rom_dir} — drop installs/shortcuts in and re-run.[/yellow]"
        )
        return

    if rename and apply_changes:
        from .pc_titles import review_titles
        title_to_path = review_titles(
            system_name, proposals,
            interactive=not no_interactive,
        )
    elif rename:
        console.print(
            f"  [yellow]would review {len(proposals)} title(s) interactively[/yellow]"
        )
        title_to_path = {p: t for p, t in proposals}
    else:
        # No interactive review — accept proposed titles, drop duplicates.
        title_to_path = {}
        for path, proposed in proposals:
            if proposed in title_to_path.values():
                continue
            title_to_path[path] = proposed

    # Invert {path: title} → {title: path} for DB + INI writes.
    by_title: dict[str, Path] = {}
    for path, title in title_to_path.items():
        by_title.setdefault(title, path)

    if not by_title:
        console.print("  [yellow]No titles accepted — nothing to write.[/yellow]")
        return

    console.print(f"  [green]+[/green] {len(by_title)} title(s) accepted")
    if not apply_changes:
        for t in sorted(by_title):
            console.print(f"  [yellow]would add stub:[/yellow] {t}")
    else:
        db = load_database(system_name, config.databases_dir)
        existing = set(db.games().keys())
        new_count = 0
        for title in sorted(by_title):
            if title in existing:
                continue
            stub = build_stub_entry(
                title,
                strip_variants=config.strip_variant_tags_in_display_name,
            )
            db.upsert_game(stub)
            new_count += 1
        if new_count:
            _tmp = config.effective_atomic_tmp_dir
            if out_base:
                saved = db.save(
                    output_path=out_base / "Databases" / system_name / f"{system_name}.xml",
                    backup=False, tmp_dir=_tmp,
                )
            else:
                _bak_dir = Path(config.backup_dir) if getattr(config, "backup_dir", "") else None
                saved = db.save(backup=config.backup_before_modify,
                                backup_dir=_bak_dir, tmp_dir=_tmp)
            console.print(f"  [green]+[/green] {new_count} stub(s) → {saved}")
        else:
            console.print("  [green]Database already in sync with titles.[/green]")

    # 4. PCLauncher per-game INIs ─────────────────────────────────────────────
    if no_pclauncher:
        console.print("[dim]6. PCLauncher INIs — skipped.[/dim]")
    else:
        console.print("\n[blue bold]6. PCLauncher per-game INIs[/blue bold]")
        if not apply_changes:
            console.print(
                f"  [yellow]would write {len(by_title)} INI(s) under "
                f"{Path(config.rocketlauncher_dir) / 'Modules' / 'PCLauncher' / system_name}[/yellow]"
            )
        else:
            from .rocketlauncher import generate_pclauncher_inis
            try:
                module_dir, written, skipped = generate_pclauncher_inis(
                    system_name, by_title, config, out_base,
                    overwrite=overwrite_pclauncher,
                )
            except ValueError as e:
                err_console.print(f"  [red]{e}[/red]")
            else:
                console.print(f"  [green]+[/green] wrote {len(written)} INI(s) → {module_dir}")
                if skipped:
                    console.print(
                        f"  [dim]· kept {len(skipped)} existing INI(s) "
                        f"(pass --overwrite-pclauncher to replace)[/dim]"
                    )

    # 5. Per-game media ──────────────────────────────────────────────────────
    if no_game_media:
        return
    console.print("\n[blue bold]7. Per-game media[/blue bold]")
    extra = ["--system", system_name]
    if pick_media:
        extra.append("--pick-media")
    if apply_changes:
        extra.append("--apply")
    if output_dir:
        extra.extend(["--output-dir", str(output_dir)])
    if source:
        extra.extend(["--source", source])
    console.print(f"  [dim]running:[/dim] spindoctor fetch-media {' '.join(extra)}")
    try:
        cli.main(args=["fetch-media", *extra], standalone_mode=False, prog_name="spindoctor")
    except SystemExit:
        pass


@cli.command("pc-rename")
@click.argument("system_name")
@click.option("--no-pclauncher", is_flag=True,
              help="Skip regenerating PCLauncher INIs after rename.")
@click.option("--overwrite-pclauncher", is_flag=True,
              help="Overwrite existing PCLauncher INIs.")
@click.option("--no-interactive", is_flag=True,
              help=("Auto-accept the proposed title for every game without "
                    "prompting. Use from non-TTY contexts (GUI, cron, CI)."))
def pc_rename(system_name, no_pclauncher, overwrite_pclauncher, no_interactive):
    """Re-run the title picker for an existing PC system.

    \b
    Use this after dropping new games into <roms_dir>/<SYSTEM>/ or to
    revise a previously-cached title.  Updates ~/.spindoctor/pc_titles_cache/
    and (optionally) regenerates the per-game PCLauncher INIs.
    """
    config = _cfg()
    _check_config(config)
    proposals = _propose_pc_titles(system_name, config)
    if not proposals:
        rom_dir = Path(config.roms_dir) / system_name
        console.print(f"[yellow]No game files found under {rom_dir}.[/yellow]")
        return

    from .pc_titles import review_titles
    title_to_path = review_titles(
        system_name, proposals, interactive=not no_interactive,
    )

    by_title: dict[str, Path] = {}
    for path, title in title_to_path.items():
        by_title.setdefault(title, path)

    console.print(f"\n[green]+[/green] {len(by_title)} title(s) confirmed.")

    if not no_pclauncher and by_title:
        from .rocketlauncher import generate_pclauncher_inis
        try:
            module_dir, written, skipped = generate_pclauncher_inis(
                system_name, by_title, config,
                overwrite=overwrite_pclauncher,
            )
        except ValueError as e:
            err_console.print(f"[red]{e}[/red]")
        else:
            console.print(f"[green]+[/green] wrote {len(written)} INI(s) → {module_dir}")
            if skipped:
                console.print(
                    f"[dim]· kept {len(skipped)} existing INI(s) "
                    f"(pass --overwrite-pclauncher to replace)[/dim]"
                )


# ─── organize ─────────────────────────────────────────────────────────────────

@cli.command("organize")
@click.argument("system_name")
@click.option("--no-sort", is_flag=True,
              help="Skip generating per-axis sort databases (genre/year/...).")
@click.option("--axes", default=",".join(("genre", "manufacturer", "year", "letter")),
              help="Comma-separated sort axes to generate. Default: all four.")
@click.option("--overwrite-sort", is_flag=True,
              help="Replace existing sort-database files (default: skip them).")
@click.option("--restructure", is_flag=True,
              help="Plan ROM folder restructuring for systems that need it "
                   "(PS3, multi-disc PS2/Saturn/Dreamcast). Dry-run by default.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Required to actually move files when --restructure is set.")
@click.option("--undo", is_flag=True,
              help="Reverse the latest restructure manifest for this system.")
def organize(system_name, no_sort, axes, overwrite_sort, restructure,
             apply_changes, undo):
    """Populate sort wheels and (optionally) restructure ROMs into folders.

    \b
    What this does:
      • Sort wheels — writes per-axis sub-databases under
        Databases/<SYSTEM>/{Genre,Manufacturer,Year,Letter}/<bucket>.xml
        so HyperSpin can render "Sort by genre / year / letter / manufacturer".
        Touches only XML; never moves ROM files.
      • --restructure (opt-in) — for systems that need per-game folders
        (PS3, multi-disc PS2/Saturn/Dreamcast) plans the moves and writes a
        manifest you can undo. Dry-run unless --apply is set.

    \b
    Examples:
      spindoctor organize "Sony Playstation"
      spindoctor organize "Sony Playstation 3" --restructure
      spindoctor organize "Sony Playstation 3" --restructure --apply
      spindoctor organize "Sony Playstation 3" --undo
    """
    from .database import write_sort_databases
    from .organize import (
        apply_restructure, find_latest_manifest, plan_restructure, undo_restructure,
    )

    config = _cfg()
    _check_config(config)

    console.print(Panel(f" organize: {system_name} ", style="bold blue"))

    # 1. Sort databases ────────────────────────────────────────────────────────
    if not no_sort:
        console.print("[blue bold]Sort databases[/blue bold]")
        db = load_database(system_name, config.databases_dir)
        games = list(db.games().values())
        if not games:
            console.print(f"  [yellow]No games in database for {system_name}.[/yellow]")
        else:
            axis_list = tuple(a.strip().lower() for a in axes.split(",") if a.strip())
            written = write_sort_databases(
                system_name, games, config.databases_dir,
                axes=axis_list, overwrite=overwrite_sort,
            )
            for axis, paths in written.items():
                if paths:
                    console.print(
                        f"  [green]+[/green] {axis}: {len(paths)} file(s) "
                        f"under {config.databases_dir / system_name / axis.capitalize()}"
                    )
                else:
                    console.print(f"  [dim]·[/dim] {axis}: no buckets / nothing to write")
    else:
        console.print("[dim]Sort databases — skipped.[/dim]")

    # 2. Undo restructure ──────────────────────────────────────────────────────
    if undo:
        console.print("\n[blue bold]Undo restructure[/blue bold]")
        manifest = find_latest_manifest(system_name, Path(config.roms_dir))
        if not manifest:
            console.print(f"  [yellow]No restructure manifest found for {system_name}.[/yellow]")
            return
        console.print(f"  Reverting from {manifest.name}")
        summary = undo_restructure(manifest)
        console.print(
            f"  [green]+[/green] reverted {summary['moves_reverted']} moves, "
            f"removed {summary['creates_removed']} generated file(s)"
        )
        for err in summary["errors"]:
            console.print(f"  [red]✗[/red] {err}")
        return

    # 3. Restructure ROM layout ────────────────────────────────────────────────
    if not restructure:
        return

    console.print("\n[blue bold]ROM restructure[/blue bold]")
    plan = plan_restructure(system_name, Path(config.roms_dir))

    for note in plan.notes:
        console.print(f"  [dim]{note}[/dim]")

    if plan.empty:
        console.print(f"  [green]No restructuring needed for {system_name}.[/green]")
        return

    tbl = Table(title=f"Plan ({plan.layout})", box=box.SIMPLE)
    tbl.add_column("From", style="yellow")
    tbl.add_column("→")
    tbl.add_column("To", style="green")
    for m in plan.moves:
        tbl.add_row(Path(m.src).name, "→", str(Path(m.dest).relative_to(Path(plan.roms_dir))))
    console.print(tbl)

    if plan.creates:
        console.print(f"  Will write {len(plan.creates)} playlist(s):")
        for c in plan.creates:
            console.print(f"    [dim]+[/dim] {Path(c.path).relative_to(Path(plan.roms_dir))}")
    if plan.skipped:
        console.print(
            f"  [dim]Skipping {len(plan.skipped)} item(s) "
            f"already organized.[/dim]"
        )

    if not apply_changes:
        console.print(
            "\n[yellow]Dry-run.[/yellow] Re-run with [cyan]--apply[/cyan] to execute."
        )
        return

    try:
        manifest = apply_restructure(plan)
    except FileExistsError as e:
        err_console.print(f"[red]Aborted:[/red] {e}")
        sys.exit(1)
    console.print(
        f"  [green]✓[/green] Applied. Manifest: {manifest.name}\n"
        f"  Run [cyan]spindoctor organize {system_name} --undo[/cyan] to revert."
    )


# ─── backup / restore ─────────────────────────────────────────────────────────

@cli.group("backup")
def backup_group():
    """Back up or restore the SpinDoctor library.

    Copy any combination of components (games, media, databases, emulators,
    rocketlauncher, ledblinky, settings) into a dated backup folder under a
    target directory. Each backup is self-describing and can be restored in
    full or in part later.

    \b
    Subcommands:
      create    Create a new backup
      list      List backups under a target directory
      info      Show what's inside a backup
      restore   Restore a backup back to the original (or current) paths
    """


@backup_group.command("create")
@click.option("--target", type=click.Path(file_okay=False), default=None,
              help="Destination folder for the backup. A new dated subfolder "
                   "named 'spindoctor-backup-YYYYMMDD_HHMMSS[-LABEL]/' is "
                   "created under it. Defaults to backup_dir from config.")
@click.option("--include", default="all",
              help="Comma-separated components to back up. Choices: roms, "
                   "databases, media, emulators, rocketlauncher, ledblinky, "
                   "settings, all. Aliases: games→roms, hyperspin→databases+media, "
                   "config→settings. Default: all.")
@click.option("--label", default=None,
              help="Optional suffix appended to the backup folder name (e.g. "
                   "'pre-migration', 'weekly').")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Execute the backup. Without this flag, prints a dry-run plan.")
@click.option("--verbose", is_flag=True,
              help="Print each file/folder being copied.")
def backup_create(target, include, label, apply_changes, verbose):
    """Create a new backup of selected library components.

    \b
    Examples:
      # Dry-run — see what would be backed up (uses backup_dir from config)
      spindoctor backup create

      # Dry-run with explicit target
      spindoctor backup create --target E:\\Backups

      # Full backup of everything
      spindoctor backup create --target E:\\Backups --apply

      # Just settings + databases
      spindoctor backup create --target E:\\Backups --include settings,databases --apply

      # Just the games (ROM files)
      spindoctor backup create --target E:\\Backups --include games --apply

      # Tagged backup — folder is suffixed with -pre-migration
      spindoctor backup create --target E:\\Backups --label pre-migration --apply
    """
    from .backup import (
        apply_backup, format_bytes, free_bytes, normalize_components,
        plan_backup,
    )

    config = _cfg()
    resolved_target = target or getattr(config, "backup_dir", "") or ""
    if not resolved_target:
        err_console.print(
            "[red]No backup target: pass --target or set backup_dir in config "
            "(spindoctor config set backup_dir <path>).[/red]"
        )
        sys.exit(1)
    target_root = Path(resolved_target).expanduser()

    try:
        components = normalize_components(include.split(","))
    except ValueError as e:
        err_console.print(f"[red]{e}[/red]")
        sys.exit(1)

    if not components:
        err_console.print("[red]--include resolved to no components.[/red]")
        sys.exit(1)

    console.print(Panel(f" backup create → {target_root} ", style="bold blue"))
    console.print(f"Components: [cyan]{', '.join(components)}[/cyan]")

    plan = plan_backup(config, target_root, components, label=label)

    if plan.skipped:
        console.print("\n[yellow]Skipped:[/yellow]")
        for s in plan.skipped:
            console.print(f"  [dim]· {s}[/dim]")

    if plan.empty:
        console.print("\n[green]Nothing to back up.[/green]")
        return

    tbl = Table(title="Backup plan", box=box.SIMPLE)
    tbl.add_column("Component", style="cyan")
    tbl.add_column("From", style="yellow")
    tbl.add_column("→")
    tbl.add_column("To", style="green")
    tbl.add_column("Size", justify="right")
    for it in plan.items:
        tbl.add_row(it.component, it.src, "→", it.dest, format_bytes(it.size_bytes))
    console.print(tbl)
    console.print(f"Backup root: [bold]{plan.backup_root}[/bold]")
    total = plan.total_bytes
    console.print(f"Total to copy: [bold]{format_bytes(total)}[/bold]")
    free = free_bytes(target_root)
    if free:
        marker = "[green]✓[/green]" if free > total else "[red]✗[/red]"
        console.print(f"Free at target: {format_bytes(free)} {marker}")
        if free <= total and apply_changes:
            err_console.print(
                "[red]Aborted:[/red] target drive does not have enough free space."
            )
            sys.exit(1)

    if not apply_changes:
        console.print(
            "\n[yellow]Dry-run.[/yellow] Re-run with [cyan]--apply[/cyan] to execute."
        )
        return

    with _make_progress(
        SpinnerColumn(),
        TextColumn("[bold]{task.description}"),
        BarColumn(),
        TextColumn("{task.completed}/{task.total}"),
        TimeElapsedColumn(),
        console=console,
    ) as progress:
        task = progress.add_task("Backing up", total=len(plan.items))

        def _cb(item, status):
            if status == "start":
                progress.update(
                    task,
                    description=f"Backing up {item.component}: {Path(item.src).name}",
                )
                if verbose:
                    progress.console.print(
                        f"[dim][verbose] copying {item.src} → {item.dest}[/dim]"
                    )
            elif status == "done":
                progress.update(task, advance=1)

        try:
            backup_root = apply_backup(plan, config, progress_cb=_cb)
        except (FileExistsError, OSError) as e:
            from ._errors import humanize_oserror
            err_console.print(
                f"[red]Aborted:[/red] {humanize_oserror(e, action='write the backup')}"
            )
            sys.exit(1)

    console.print(f"\n[green]✓[/green] Backup complete: {backup_root}")
    console.print(
        f"  Run [cyan]spindoctor backup restore --backup \"{backup_root}\"[/cyan] "
        f"to restore."
    )


@backup_group.command("list")
@click.option("--target", type=click.Path(file_okay=False), default=None,
              help="Folder where backups live (the same path passed to "
                   "`backup create --target`). Defaults to backup_dir from config.")
@click.option("--json", "as_json", is_flag=True,
              help="Emit JSON instead of a human-readable table — used by "
                   "the GUI's Backup tab restore picker.")
def backup_list(target, as_json):
    """List backups under a target folder."""
    from .backup import format_bytes, list_backups, read_manifest

    config = _cfg()
    resolved_target = target or getattr(config, "backup_dir", "") or ""
    if not resolved_target:
        err_console.print(
            "[red]No target: pass --target or set backup_dir in config "
            "(spindoctor config set backup_dir <path>).[/red]"
        )
        sys.exit(1)
    target_root = Path(resolved_target).expanduser()
    backups = list_backups(target_root)
    if as_json:
        # The GUI's _scan_backup_folders consumes this shape: a list of
        # dicts with at least ``name`` + ``path`` so the restore combobox
        # can populate without re-implementing directory traversal.
        entries: list[dict] = []
        for b in backups:
            entry = {"name": b.name, "path": str(b)}
            try:
                data = read_manifest(b)
                entry["timestamp"] = data.get("timestamp", "")
                entry["components"] = [
                    i["component"] for i in data.get("items", [])
                ]
                entry["size_bytes"] = sum(
                    i.get("size_bytes", 0) for i in data.get("items", [])
                )
            except (FileNotFoundError, ValueError):
                entry["malformed"] = True
            entries.append(entry)
        click.echo(json.dumps(entries, indent=2))
        return
    if not backups:
        console.print(f"[yellow]No backups found under {target_root}.[/yellow]")
        return

    tbl = Table(title=f"Backups under {target_root}", box=box.SIMPLE)
    tbl.add_column("Backup", style="cyan")
    tbl.add_column("Timestamp")
    tbl.add_column("Components")
    tbl.add_column("Size", justify="right")
    for b in backups:
        try:
            data = read_manifest(b)
            comps = ", ".join(i["component"] for i in data.get("items", []))
            size = sum(i.get("size_bytes", 0) for i in data.get("items", []))
            tbl.add_row(b.name, data.get("timestamp", ""), comps or "[dim]none[/dim]",
                        format_bytes(size))
        except (FileNotFoundError, ValueError):
            tbl.add_row(b.name, "[red]?[/red]", "[red]malformed manifest[/red]", "")
    console.print(tbl)


@backup_group.command("info")
@click.option("--backup", "backup_path", type=click.Path(file_okay=False),
              required=True,
              help="Path to a backup folder (created by `backup create`).")
def backup_info(backup_path):
    """Show what's inside a backup."""
    from .backup import format_bytes, read_manifest

    backup_root = Path(backup_path).expanduser()
    try:
        data = read_manifest(backup_root)
    except (FileNotFoundError, ValueError) as e:
        err_console.print(f"[red]{e}[/red]")
        sys.exit(1)

    console.print(Panel(f" {backup_root.name} ", style="bold blue"))
    console.print(f"Created: [cyan]{data.get('timestamp', '?')}[/cyan]")
    console.print(f"Path:    [dim]{backup_root}[/dim]")

    items = data.get("items", [])
    if not items:
        console.print("\n[yellow]Backup contains no components.[/yellow]")
        return

    tbl = Table(title="Components", box=box.SIMPLE)
    tbl.add_column("Component", style="cyan")
    tbl.add_column("Original source", style="yellow")
    tbl.add_column("Size", justify="right")
    for i in items:
        tbl.add_row(i["component"], i["src"], format_bytes(i.get("size_bytes", 0)))
    console.print(tbl)
    total = sum(i.get("size_bytes", 0) for i in items)
    console.print(f"Total: [bold]{format_bytes(total)}[/bold]")


@backup_group.command("restore")
@click.option("--backup", "backup_path", type=click.Path(file_okay=False),
              required=True,
              help="Path to the backup folder to restore.")
@click.option("--include", default=None,
              help="Comma-separated components to restore (default: every "
                   "component recorded in the backup). Same vocabulary as "
                   "`backup create --include`.")
@click.option("--use-current-paths", is_flag=True,
              help="Restore each component to the path currently set in "
                   "~/.spindoctor/config.json instead of the path recorded "
                   "in the backup manifest. Useful when drive letters changed.")
@click.option("--overwrite", is_flag=True,
              help="Replace existing destination folders. Without this flag, "
                   "restore aborts if any destination is non-empty.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Execute the restore. Without this flag, prints a dry-run plan.")
@click.option("--verbose", is_flag=True,
              help="Print each file/folder being restored.")
def backup_restore(backup_path, include, use_current_paths, overwrite, apply_changes, verbose):
    """Restore from a backup back to the library paths.

    \b
    Examples:
      # Dry-run — see what would be restored
      spindoctor backup restore --backup E:\\Backups\\spindoctor-backup-20260428_120000

      # Full restore
      spindoctor backup restore --backup E:\\... --apply

      # Just restore settings (config + favorites)
      spindoctor backup restore --backup E:\\... --include settings --apply

      # Drive letters changed since the backup — route everything to the
      # paths now in config.json
      spindoctor backup restore --backup E:\\... --use-current-paths --apply

      # Replace existing folders on disk
      spindoctor backup restore --backup E:\\... --overwrite --apply
    """
    from .backup import (
        apply_restore, format_bytes, plan_restore,
    )

    backup_root = Path(backup_path).expanduser()
    components = None
    if include:
        components = [c.strip() for c in include.split(",") if c.strip()]

    config_for_routing = _cfg() if use_current_paths else None

    try:
        plan = plan_restore(
            backup_root,
            components=components,
            use_current_config=config_for_routing,
        )
    except (FileNotFoundError, ValueError) as e:
        err_console.print(f"[red]{e}[/red]")
        sys.exit(1)

    console.print(Panel(f" backup restore ← {backup_root.name} ", style="bold blue"))

    if plan.skipped:
        console.print("[yellow]Skipped:[/yellow]")
        for s in plan.skipped:
            console.print(f"  [dim]· {s}[/dim]")

    if plan.empty:
        console.print("\n[green]Nothing to restore.[/green]")
        return

    tbl = Table(title="Restore plan", box=box.SIMPLE)
    tbl.add_column("Component", style="cyan")
    tbl.add_column("From backup", style="yellow")
    tbl.add_column("→")
    tbl.add_column("Restored to", style="green")
    tbl.add_column("Size", justify="right")
    for it in plan.items:
        tbl.add_row(it.component, it.src, "→", it.dest, format_bytes(it.size_bytes))
    console.print(tbl)
    console.print(f"Total to restore: [bold]{format_bytes(plan.total_bytes)}[/bold]")

    # Warn about clobbering
    clobbers = [i for i in plan.items if Path(i.dest).exists()
                and (Path(i.dest).is_file() or any(Path(i.dest).iterdir()))]
    if clobbers and not overwrite:
        console.print(
            "\n[red]The following destinations already exist[/red] "
            "(pass [cyan]--overwrite[/cyan] to replace them):"
        )
        for c in clobbers:
            console.print(f"  · {c.dest}")
        if apply_changes:
            err_console.print(
                "[red]Aborted:[/red] re-run with --overwrite or remove the "
                "existing folders first."
            )
            sys.exit(1)

    if not apply_changes:
        console.print(
            "\n[yellow]Dry-run.[/yellow] Re-run with [cyan]--apply[/cyan] to execute."
        )
        return

    with _make_progress(
        SpinnerColumn(),
        TextColumn("[bold]{task.description}"),
        BarColumn(),
        TextColumn("{task.completed}/{task.total}"),
        TimeElapsedColumn(),
        console=console,
    ) as progress:
        task = progress.add_task("Restoring", total=len(plan.items))

        def _cb(item, status):
            if status == "start":
                progress.update(
                    task,
                    description=f"Restoring {item.component} → {Path(item.dest).name}",
                )
                if verbose:
                    progress.console.print(
                        f"[dim][verbose] restoring {item.src} → {item.dest}[/dim]"
                    )
            elif status == "done":
                progress.update(task, advance=1)

        try:
            restored = apply_restore(plan, overwrite=overwrite, progress_cb=_cb)
        except (FileExistsError, OSError) as e:
            from ._errors import humanize_oserror
            err_console.print(
                f"[red]Aborted:[/red] {humanize_oserror(e, action='restore from the backup')}"
            )
            sys.exit(1)

    console.print(f"\n[green]✓[/green] Restored {restored} component(s).")


# ─── per-modify sidecar backups (.YYYYMMDD_HHMMSS.bak files) ─────────────────


def _sidecar_pattern(path: Path):
    """Compile the regex that matches sidecar siblings of *path*.

    SpinDoctor's apply commands write ``<stem>.YYYYMMDD_HHMMSS.bak``
    next to each mutated file via ``Path.with_suffix(...)``. For
    ``Main Menu.xml`` that's ``Main Menu.20260519_153045.bak`` —
    ``stem`` is ``Main Menu``, the timestamp is 8+1+6 digits.
    """
    import re as _re
    return _re.compile(
        rf"^{_re.escape(path.stem)}\.\d{{8}}_\d{{6}}\.bak$"
    )


def _find_sidecars(path: Path) -> list[Path]:
    """Return sidecar ``.bak`` siblings of *path*, newest first."""
    if not path.parent.exists():
        return []
    pat = _sidecar_pattern(path)
    matches = [p for p in path.parent.iterdir() if pat.match(p.name)]
    # The timestamp lexicographically sorts as chronological order, so
    # ``sort(reverse=True)`` puts newest first without needing mtime.
    matches.sort(key=lambda p: p.name, reverse=True)
    return matches


@backup_group.group("sidecar")
def backup_sidecar_group():
    """List and restore the per-modify ``.YYYYMMDD_HHMMSS.bak`` sidecars
    SpinDoctor's apply commands write next to each mutated file.

    These are distinct from ``backup create / restore`` — those operate
    on full library backup folders, while sidecars are tiny per-file
    snapshots written automatically when ``backup_before_modify`` is on
    (the default). Use these subcommands to inspect or roll back a
    single bad edit (e.g. a Main Menu.xml that left HyperSpin throwing
    "Error creating main menu").
    """


@backup_sidecar_group.command("list")
@click.argument("file", type=click.Path(dir_okay=False, path_type=Path))
@click.option("--json", "as_json", is_flag=True,
              help="Emit JSON instead of a human-readable table — used by "
                   "the GUI's Restore-from-backup picker.")
def backup_sidecar_list(file, as_json):
    """List ``.YYYYMMDD_HHMMSS.bak`` siblings of FILE, newest first.

    \b
    Examples:
      # See every Main Menu.xml backup currently on disk
      spindoctor backup sidecar list "D:/HyperSpin/Databases/Main Menu/Main Menu.xml"
    """
    file = file.expanduser()
    matches = _find_sidecars(file)
    if as_json:
        click.echo(json.dumps([
            {
                "path": str(p),
                "name": p.name,
                "size": p.stat().st_size,
                "mtime": p.stat().st_mtime,
            } for p in matches
        ], indent=2))
        return
    if not matches:
        console.print(
            f"[yellow]No .bak sidecars found next to {file}.[/yellow]"
        )
        return
    tbl = Table(title=f"Sidecar backups of {file.name}", box=box.SIMPLE)
    tbl.add_column("Name", style="cyan")
    tbl.add_column("Size", justify="right")
    tbl.add_column("Modified", style="dim")
    for p in matches:
        st = p.stat()
        mtime = datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M:%S")
        tbl.add_row(p.name, f"{st.st_size:,} B", mtime)
    console.print(tbl)


@backup_sidecar_group.command("restore")
@click.argument("file", type=click.Path(dir_okay=False, path_type=Path))
@click.option("--from", "source",
              type=click.Path(exists=True, dir_okay=False, path_type=Path),
              required=True,
              help="The .YYYYMMDD_HHMMSS.bak sidecar to restore (use "
                   "``backup sidecar list`` to see options).")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Execute the restore. Without this flag, prints the "
                   "intended copy as a dry-run.")
def backup_sidecar_restore(file, source, apply_changes):
    """Restore FILE from a ``.YYYYMMDD_HHMMSS.bak`` sidecar.

    Backs up the current FILE first (when it exists) so the restore
    itself can be rolled back via another ``backup sidecar restore``
    call — undo is one of the things the per-modify sidecars exist for
    and ``--apply`` shouldn't be a one-way door.

    \b
    Examples:
      # Dry-run (default) — see what would happen
      spindoctor backup sidecar restore "D:/.../Main Menu.xml" \\
          --from "D:/.../Main Menu.20260519_153045.bak"

      # Commit the restore
      spindoctor backup sidecar restore "D:/.../Main Menu.xml" \\
          --from "D:/.../Main Menu.20260519_153045.bak" --apply
    """
    file = file.expanduser()
    source = source.expanduser()
    if not source.name.endswith(".bak"):
        err_console.print(
            f"[red]Refusing:[/red] --from must point to a .bak file, "
            f"got {source.name}."
        )
        sys.exit(1)
    pat = _sidecar_pattern(file)
    if not pat.match(source.name):
        err_console.print(
            f"[red]Refusing:[/red] {source.name} doesn't look like a "
            f"sidecar of {file.name} (expected ``{file.stem}.YYYYMMDD_HHMMSS.bak``)."
        )
        sys.exit(1)
    if not apply_changes:
        console.print(
            f"[yellow]Dry-run.[/yellow] Would copy:\n"
            f"  [cyan]{source}[/cyan]\n  → [green]{file}[/green]"
        )
        if file.exists():
            console.print(
                "  (current file would be sidecar-backed-up first.)"
            )
        console.print("\nRe-run with [cyan]--apply[/cyan] to commit.")
        return
    # Backup the current live file before overwriting it so the user
    # can undo the restore via another ``sidecar restore`` call.
    if file.exists():
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        live_backup = file.with_suffix(f".{stamp}.bak")
        try:
            shutil.copy2(file, live_backup)
        except OSError as e:
            from ._errors import humanize_oserror
            err_console.print(
                f"[red]Aborted:[/red] {humanize_oserror(e, action='back up the current file')}"
            )
            sys.exit(1)
        console.print(f"[dim]Saved current file as {live_backup.name}[/dim]")
    try:
        shutil.copy2(source, file)
    except OSError as e:
        from ._errors import humanize_oserror
        err_console.print(
            f"[red]Aborted:[/red] {humanize_oserror(e, action='restore the sidecar')}"
        )
        sys.exit(1)
    console.print(f"[green]✓[/green] Restored {file.name} from {source.name}.")


# ─── diff (compare backup to live tree) ──────────────────────────────────────


@cli.command("diff")
@click.argument("backup_folder", type=click.Path(exists=True, file_okay=False))
@click.option("--component", default=None,
              help="Limit the diff to one component (roms, databases, media, etc.).")
def diff(backup_folder, component):
    """Compare a spindoctor-backup-… folder against the live cabinet tree.

    \b
    Lists which files have been added, deleted, or modified in each
    backed-up component since the snapshot was taken. Comparison is by
    file size and modification time (fast; no full hash). Useful for
    answering "what changed since last week?" without manually diffing
    folders.

    \b
    Examples:
      spindoctor diff E:\\Backups\\spindoctor-backup-20260101_120000
      spindoctor diff E:\\Backups\\spindoctor-backup-20260101_120000 --component databases
    """
    from .backup import read_manifest

    backup_root = Path(backup_folder).expanduser()
    try:
        manifest = read_manifest(backup_root)
    except (FileNotFoundError, ValueError) as exc:
        err_console.print(f"[red]Could not read manifest:[/red] {exc}")
        sys.exit(1)

    items = manifest.get("items", [])
    if component:
        items = [i for i in items if i.get("component") == component]
        if not items:
            err_console.print(
                f"[yellow]No component '{component}' in this backup.[/yellow] "
                f"Available: {', '.join(i['component'] for i in manifest.get('items', []))}"
            )
            sys.exit(1)

    console.print(
        Panel(
            f" diff  backup: {backup_root.name} ",
            style="bold blue",
        )
    )
    ts = manifest.get("timestamp", "unknown")
    console.print(f"Backup taken: [dim]{ts}[/dim]\n")

    grand_added = grand_deleted = grand_modified = 0

    for item in items:
        comp = item.get("component", "?")
        live_str = item.get("src", "")
        snap_str = item.get("dest", "")

        live_root = Path(live_str) if live_str else None
        snap_root = Path(snap_str) if snap_str else None

        console.print(f"[bold cyan]{comp}[/bold cyan]")

        if not live_root or not live_root.exists():
            console.print(f"  [yellow]Live path not found:[/yellow] {live_root}")
            console.print()
            continue
        if not snap_root or not snap_root.exists():
            console.print(f"  [yellow]Backup path not found:[/yellow] {snap_root}")
            console.print()
            continue

        # Build index: relative path → (size, mtime) for both trees.
        def _index(root: Path) -> dict:
            idx: dict = {}
            for p in root.rglob("*"):
                if not p.is_file():
                    continue
                try:
                    st = p.stat()
                    idx[p.relative_to(root)] = (st.st_size, int(st.st_mtime))
                except OSError:
                    pass
            return idx

        live_idx = _index(live_root)
        snap_idx = _index(snap_root)

        live_keys = set(live_idx)
        snap_keys = set(snap_idx)

        added = sorted(live_keys - snap_keys)
        deleted = sorted(snap_keys - live_keys)
        modified = sorted(
            k for k in live_keys & snap_keys
            if live_idx[k] != snap_idx[k]
        )

        if not added and not deleted and not modified:
            console.print("  [green]No changes.[/green]")
        else:
            for k in added:
                console.print(f"  [green]+[/green] {k}")
            for k in deleted:
                console.print(f"  [red]−[/red] {k}")
            for k in modified:
                console.print(f"  [yellow]~[/yellow] {k}")

        count_parts = []
        if added:
            count_parts.append(f"[green]{len(added)} added[/green]")
        if deleted:
            count_parts.append(f"[red]{len(deleted)} deleted[/red]")
        if modified:
            count_parts.append(f"[yellow]{len(modified)} modified[/yellow]")
        if count_parts:
            console.print(f"  → {', '.join(count_parts)}")
        console.print()

        grand_added += len(added)
        grand_deleted += len(deleted)
        grand_modified += len(modified)

    total = grand_added + grand_deleted + grand_modified
    if total == 0:
        console.print("[green]✓ No differences found.[/green]")
    else:
        console.print(
            f"Total: [green]{grand_added} added[/green]  "
            f"[red]{grand_deleted} deleted[/red]  "
            f"[yellow]{grand_modified} modified[/yellow]"
        )


# ─── migrate (move library to a new drive) ────────────────────────────────────

@cli.command("migrate")
@click.option("--target", type=click.Path(file_okay=False), default=None,
              help="Destination root folder on the new drive. New per-component "
                   "subfolders (ROMs/, HyperSpin/, ...) are created underneath.")
@click.option("--include", default="all",
              help="Comma-separated components to migrate. Choices: "
                   "roms, hyperspin, emulators, rocketlauncher, ledblinky, all. "
                   "Aliases: games→roms, media/data/databases→hyperspin. "
                   "Default: all.")
@click.option("--systems", default=None,
              help="Comma-separated systems to migrate (only applies to --include roms). "
                   "When set, only those system subfolders are moved and "
                   "roms_dir config is left unchanged.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Execute the migration. Without this flag, prints a dry-run plan.")
@click.option("--keep-source", is_flag=True,
              help="Copy instead of move — leaves the source intact. Pair with "
                   "--verify for a safe-then-delete-by-hand workflow.")
@click.option("--verify", is_flag=True,
              help="SHA1-verify each file after copy. Only meaningful with --keep-source.")
@click.option("--no-update-config", is_flag=True,
              help="Don't rewrite ~/.spindoctor/config.json with the new paths.")
@click.option("--preserve-names", is_flag=True,
              help="Keep each component's original folder name at the target "
                   "(e.g. D:\\MyArcade\\HS lands at <target>/HS). "
                   "Default: standardized names — Games, HyperSpin, Emulators, "
                   "RocketLauncher, LEDBlinky.")
@click.option("--undo", "undo_path", default=None,
              help="Path to a manifest under ~/.spindoctor/migrations/ to reverse. "
                   "Use 'latest' to undo the most recent migration.")
@click.option("--list-manifests", is_flag=True,
              help="List all migration manifests on disk and exit.")
@click.option("--verbose", is_flag=True, help="Print each file/folder path as it is moved or copied.")
def migrate(target, include, systems, apply_changes, keep_source, verify,
            no_update_config, preserve_names, undo_path, list_manifests, verbose):
    """Migrate the library to a new drive.

    \b
    Move (or copy) ROMs, HyperSpin, Emulators, RocketLauncher, and LEDBlinky
    folders to a new drive in one shot. Updates ~/.spindoctor/config.json so
    SpinDoctor keeps working at the new location. Every applied migration
    writes a manifest you can undo.

    \b
    Examples:
      # See what would move (dry run, every component)
      spindoctor migrate --target E:\\NewCab

      # Move everything and update config
      spindoctor migrate --target E:\\NewCab --apply

      # Move only the ROMs and HyperSpin folder
      spindoctor migrate --target E:\\NewCab --include roms,hyperspin --apply

      # Aliases — these are equivalent to --include roms,hyperspin
      spindoctor migrate --target E:\\NewCab --include games,media --apply

      # Move only specific systems' ROMs (config unchanged)
      spindoctor migrate --target E:\\NewCab --include roms \\
          --systems "MAME,Sony Playstation 3" --apply

      # Safe copy + verify (keeps the original intact)
      spindoctor migrate --target E:\\NewCab --apply --keep-source --verify

      # Reverse the most recent migration
      spindoctor migrate --undo latest
      spindoctor migrate --list-manifests
    """
    from .migrate import (
        MIGRATIONS_DIR, apply_migration, find_latest_manifest,
        format_bytes, free_bytes, list_manifests as list_migrate_manifests,
        normalize_components, plan_migration, undo_migration,
    )

    # ── --list-manifests ──────────────────────────────────────────────────────
    if list_manifests:
        manifests = list_migrate_manifests()
        if not manifests:
            console.print(f"[yellow]No migration manifests under {MIGRATIONS_DIR}.[/yellow]")
            return
        tbl = Table(title="Migration manifests", box=box.SIMPLE)
        tbl.add_column("Manifest", style="cyan")
        tbl.add_column("Target")
        tbl.add_column("Mode")
        for m in manifests:
            try:
                import json as _json
                data = _json.loads(m.read_text(encoding="utf-8"))
                mode = "copy" if data.get("keep_source") else "move"
                tbl.add_row(m.name, data.get("target_root", ""), mode)
            except (OSError, ValueError):
                tbl.add_row(m.name, "[red]?[/red]", "[red]?[/red]")
        console.print(tbl)
        return

    # ── --undo ────────────────────────────────────────────────────────────────
    if undo_path:
        if undo_path == "latest":
            manifest = find_latest_manifest()
            if not manifest:
                err_console.print("[red]No migration manifests to undo.[/red]")
                sys.exit(1)
        else:
            manifest = Path(undo_path)
            if not manifest.exists():
                err_console.print(f"[red]Manifest not found:[/red] {manifest}")
                sys.exit(1)
        console.print(f"[blue bold]Undo migration[/blue bold]: {manifest.name}")
        summary = undo_migration(manifest)
        console.print(
            f"  [green]+[/green] reverted {summary['moves_reverted']} move(s), "
            f"removed {summary['destinations_removed']} copied destination(s)"
        )
        if summary["config_restored"]:
            console.print("  [green]+[/green] config restored from snapshot")
        for err in summary["errors"]:
            console.print(f"  [red]✗[/red] {err}")
        return

    # ── plan / apply path ─────────────────────────────────────────────────────
    if not target:
        err_console.print(
            "[red]--target is required (unless using --undo or --list-manifests).[/red]"
        )
        sys.exit(1)

    config = _cfg()
    target_root = Path(target).expanduser()

    try:
        components = normalize_components(include.split(","))
    except ValueError as e:
        err_console.print(f"[red]{e}[/red]")
        sys.exit(1)

    if not components:
        err_console.print("[red]--include resolved to no components.[/red]")
        sys.exit(1)

    systems_filter = None
    if systems:
        systems_filter = [s.strip() for s in systems.split(",") if s.strip()]
        if "roms" not in components:
            console.print(
                "[yellow]--systems only filters the 'roms' component; "
                "ignoring for everything else.[/yellow]"
            )

    console.print(Panel(f" migrate → {target_root} ", style="bold blue"))
    console.print(f"Components: [cyan]{', '.join(components)}[/cyan]")
    if systems_filter:
        console.print(f"Systems filter (roms only): [cyan]{', '.join(systems_filter)}[/cyan]")

    plan = plan_migration(
        config, target_root, components, systems_filter,
        preserve_names=preserve_names,
    )

    for note in plan.notes:
        console.print(f"  [dim]{note}[/dim]")

    if plan.skipped:
        console.print("\n[yellow]Skipped:[/yellow]")
        for s in plan.skipped:
            console.print(f"  [dim]· {s}[/dim]")

    if plan.empty:
        console.print("\n[green]Nothing to migrate.[/green]")
        return

    tbl = Table(title="Migration plan", box=box.SIMPLE)
    tbl.add_column("Component", style="cyan")
    tbl.add_column("From", style="yellow")
    tbl.add_column("→")
    tbl.add_column("To", style="green")
    tbl.add_column("Size", justify="right")
    for m in plan.moves:
        tbl.add_row(m.component, m.src, "→", m.dest, format_bytes(m.size_bytes))
    console.print(tbl)

    total = plan.total_bytes
    console.print(f"Total to transfer: [bold]{format_bytes(total)}[/bold]")
    free = free_bytes(target_root)
    if free:
        marker = "[green]✓[/green]" if free > total else "[red]✗[/red]"
        console.print(f"Free at target: {format_bytes(free)} {marker}")
        if free <= total and apply_changes:
            err_console.print(
                "[red]Aborted:[/red] target drive does not have enough free space."
            )
            sys.exit(1)

    if plan.config_updates and not no_update_config and not keep_source:
        console.print("\nConfig updates that will be applied:")
        for k, v in plan.config_updates.items():
            console.print(f"  [cyan]{k}[/cyan] → {v}")
    elif keep_source:
        console.print("\n[dim]--keep-source: config will NOT be updated.[/dim]")

    if not apply_changes:
        console.print(
            "\n[yellow]Dry-run.[/yellow] Re-run with [cyan]--apply[/cyan] to execute."
        )
        return

    # ── execute ───────────────────────────────────────────────────────────────
    with _make_progress(
        SpinnerColumn(),
        TextColumn("[bold]{task.description}"),
        BarColumn(),
        TextColumn("{task.completed}/{task.total}"),
        TimeElapsedColumn(),
        console=console,
    ) as progress:
        task = progress.add_task("Migrating", total=len(plan.moves))

        def _cb(move, status):
            if status == "start":
                progress.update(task, description=f"Migrating {move.component}: {Path(move.src).name}")
                if verbose:
                    action = "copying" if keep_source else "moving"
                    progress.console.print(f"[dim][verbose] {action} {move.src} → {move.dest}[/dim]")
            elif status == "done":
                progress.update(task, advance=1)

        try:
            manifest = apply_migration(
                plan,
                keep_source=keep_source,
                verify=verify,
                update_config=not no_update_config,
                progress_cb=_cb,
            )
        except (FileExistsError, RuntimeError, OSError) as e:
            from ._errors import humanize_oserror
            msg = humanize_oserror(e, action="migrate the library") if isinstance(e, OSError) else str(e)
            err_console.print(f"[red]Aborted:[/red] {msg}")
            sys.exit(1)

    console.print(f"\n[green]✓[/green] Migration complete. Manifest: {manifest}")
    console.print(
        f"  Run [cyan]spindoctor migrate --undo {manifest}[/cyan] to revert."
    )
    if "roms" in components and not keep_source and not no_update_config:
        console.print(
            "\n[yellow]Next step:[/yellow] RocketLauncher's per-system INIs still "
            "contain the old Rom_Path. Regenerate them now:\n"
            "  [cyan]spindoctor generate-config --apply[/cyan]\n"
            "GUI: Metadata & Media tab → Run generate-config (with Apply ticked)."
        )


# ─── batch-edit / rename / clone ─────────────────────────────────────────────


def _print_edit_table(plan: dict, title: str) -> None:
    """Render a (game | field | before -> after) table from a plan dict."""
    tbl = Table(title=title, box=box.SIMPLE)
    tbl.add_column("Game", style="cyan", overflow="fold")
    tbl.add_column("Field")
    tbl.add_column("Before", style="yellow", overflow="fold")
    tbl.add_column("After", style="green", overflow="fold")
    for game_name in sorted(plan.keys(), key=str.lower):
        for field_name, (before, after) in plan[game_name].items():
            tbl.add_row(
                game_name, field_name,
                escape(before) if before else "[dim](empty)[/dim]",
                escape(after) if after else "[dim](empty)[/dim]",
            )
    console.print(tbl)


@cli.command("batch-edit")
@click.option("--system", "-s", required=False, default=None,
              help="System whose database to edit.")
@click.option("--filter", "filters", multiple=True,
              help="Filter clause: name=*Mario*, genre=Action, year=1980-1989, "
                   "manufacturer=Nintendo, missing=rating. May be repeated.")
@click.option("--set", "set_clauses", multiple=True,
              help="Set a field: --set genre=Action. May be repeated.")
@click.option("--clear", "clear_fields", multiple=True,
              help="Clear a field: --clear rating. May be repeated.")
@click.option("--append", "append_clauses", multiple=True,
              help="Append text to a field: --append description=' (USA)'.")
@click.option("--prepend", "prepend_clauses", multiple=True,
              help="Prepend text to a field. May be repeated.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Execute the edit. Without this flag, dry-run only.")
@click.option("--report", "report_path", default=None, type=click.Path(),
              help="Write a CSV preview to this path (game,field,before,after).")
@click.option("--undo", "undo_manifest", default=None, type=click.Path(exists=True),
              help="Reverse the edit recorded in this manifest.")
@click.option("--list-manifests", "list_manifests_flag", is_flag=True,
              help="List edit manifests on disk and exit.")
@click.option("--output-dir", default=None, type=click.Path(),
              help="Write the edited DB into <output-dir>/Databases/<system>/ "
                   "instead of the live HyperSpin tree.")
def batch_edit(system, filters, set_clauses, clear_fields, append_clauses,
               prepend_clauses, apply_changes, report_path, undo_manifest,
               list_manifests_flag, output_dir):
    """Edit metadata fields across many games in one shot.

    \b
    Examples:
      spindoctor batch-edit --system MAME --filter genre=Action --set rating=5
      spindoctor batch-edit --system MAME --filter year=1980-1989 \\
                            --filter manufacturer=Capcom --set genre=Action --apply
      spindoctor batch-edit --system MAME --filter missing=rating --set rating=3
      spindoctor batch-edit --undo ~/.spindoctor/edits/edit-20260428_120000.json
      spindoctor batch-edit --list-manifests
    """
    from .edit import (
        EDIT_DIR, EditChange, apply_batch_edit, build_filter,
        edit_manifest_summary, find_matching_games, list_edit_manifests,
        plan_batch_edit, undo_batch_edit, write_edit_report,
    )

    config = _cfg()

    # ── --list-manifests ──────────────────────────────────────────────────────
    if list_manifests_flag:
        manifests = list_edit_manifests()
        if not manifests:
            console.print(
                f"[yellow]No edit manifests under {EDIT_DIR}.[/yellow]"
            )
            return
        tbl = Table(title="Batch-edit manifests", box=box.SIMPLE)
        tbl.add_column("Manifest", style="cyan")
        tbl.add_column("System")
        tbl.add_column("Games", justify="right")
        tbl.add_column("Changes", justify="right")
        for m in manifests:
            info = edit_manifest_summary(m)
            tbl.add_row(
                m.name,
                info["system"] or "[dim]?[/dim]",
                str(info["games"]),
                str(info["changes"]),
            )
        console.print(tbl)
        return

    # ── --undo ────────────────────────────────────────────────────────────────
    if undo_manifest:
        _check_config(config)
        manifest_path = Path(undo_manifest)
        console.print(f"Reverting {manifest_path.name}")
        results = undo_batch_edit(manifest_path, config)
        reverted = sum(1 for r in results if not r.skipped)
        skipped = sum(1 for r in results if r.skipped)
        console.print(
            f"[green]+[/green] reverted {reverted} game(s); "
            f"skipped {skipped}"
        )
        for r in results:
            if r.skipped:
                err_console.print(f"  [yellow]·[/yellow] {r.game_name} — {r.reason}")
        return

    # ── plan path ─────────────────────────────────────────────────────────────
    if not system:
        err_console.print("[red]--system is required for batch-edit.[/red]")
        sys.exit(1)
    _check_config(config)

    try:
        edit_filter = build_filter(system, filters)
    except ValueError as e:
        err_console.print(f"[red]Bad --filter:[/red] {e}")
        sys.exit(1)

    changes: list[EditChange] = []
    try:
        for clause in set_clauses:
            key, value = clause.split("=", 1) if "=" in clause else (clause, "")
            changes.append(EditChange(field=key.strip().lower(), value=value, mode="set"))
        for fname in clear_fields:
            changes.append(EditChange(field=fname.strip().lower(), value="", mode="clear"))
        for clause in append_clauses:
            key, value = clause.split("=", 1) if "=" in clause else (clause, "")
            changes.append(EditChange(field=key.strip().lower(), value=value, mode="append"))
        for clause in prepend_clauses:
            key, value = clause.split("=", 1) if "=" in clause else (clause, "")
            changes.append(EditChange(field=key.strip().lower(), value=value, mode="prepend"))
    except ValueError as e:
        err_console.print(f"[red]Bad change spec:[/red] {e}")
        sys.exit(1)

    if not changes:
        err_console.print(
            "[red]No changes specified. Use --set / --clear / --append / --prepend.[/red]"
        )
        sys.exit(1)

    games = find_matching_games(config, edit_filter)
    if not games:
        console.print("[yellow]No games match the filter.[/yellow]")
        return

    plan = plan_batch_edit(games, changes)
    if not plan:
        console.print("[yellow]Filter matched games but no fields would change.[/yellow]")
        return

    console.print(Panel(
        f" batch-edit — {system}: {len(plan)} game(s), "
        f"{sum(len(v) for v in plan.values())} field change(s) ",
        style="bold blue",
    ))
    _print_edit_table(plan, title=f"{system} — pending edits")

    if report_path:
        out = Path(report_path)
        write_edit_report(games, changes, out)
        console.print(f"[dim]CSV report:[/dim] {out}")

    if not apply_changes:
        console.print(
            f"\n[yellow]{len(plan)}[/yellow] game(s) would be edited. "
            f"Re-run with [cyan]--apply[/cyan] to write."
        )
        return

    out_path = Path(output_dir) if output_dir else None
    results, manifest = apply_batch_edit(
        config, system, games, changes, output_dir=out_path,
    )
    edited = sum(1 for r in results if not r.skipped)
    console.print(f"\n[green]+[/green] edited {edited} game(s)")
    for r in results:
        if r.skipped:
            console.print(f"  [dim]·[/dim] {r.game_name} — {r.reason}")
    if manifest:
        console.print(
            f"Manifest: {manifest.name}\n"
            f"  Run [cyan]spindoctor batch-edit --undo {manifest}[/cyan] to revert."
        )


def _print_rename_table(plan, title: str) -> None:
    tbl = Table(title=title, box=box.SIMPLE)
    tbl.add_column("Kind", style="cyan")
    tbl.add_column("From", overflow="fold")
    tbl.add_column("To", overflow="fold")
    tbl.add_column("Note", style="dim", overflow="fold")
    for ch in plan.file_changes:
        src = str(ch.src) if ch.src else "[dim]—[/dim]"
        dest = str(ch.dest) if ch.dest else "[dim]—[/dim]"
        kind = ch.kind if not ch.media_type else f"{ch.kind} ({ch.media_type})"
        tbl.add_row(kind, escape(src), escape(dest), ch.note)
    console.print(tbl)


def _do_rename_or_clone(*, clone: bool, system, game, to, display_name,
                        apply_changes, undo_manifest, list_manifests_flag,
                        output_dir, verbose: bool = False):
    from .edit import (
        RENAME_DIR, apply_rename, list_rename_manifests, plan_rename,
        rename_manifest_summary, undo_rename,
    )

    config = _cfg()
    verb = "clone" if clone else "rename"

    if list_manifests_flag:
        manifests = list_rename_manifests()
        if not manifests:
            console.print(f"[yellow]No rename manifests under {RENAME_DIR}.[/yellow]")
            return
        tbl = Table(title="Rename / clone manifests", box=box.SIMPLE)
        tbl.add_column("Manifest", style="cyan")
        tbl.add_column("System")
        tbl.add_column("Old")
        tbl.add_column("New")
        tbl.add_column("Mode")
        tbl.add_column("Files", justify="right")
        for m in manifests:
            info = rename_manifest_summary(m)
            tbl.add_row(
                m.name,
                info["system"] or "[dim]?[/dim]",
                info["old"] or "",
                info["new"] or "",
                "clone" if info["clone"] else "rename",
                str(info["moves"]),
            )
        console.print(tbl)
        return

    if undo_manifest:
        _check_config(config)
        manifest_path = Path(undo_manifest)
        console.print(f"Reverting {manifest_path.name}")
        reversed_changes = undo_rename(manifest_path, config)
        ok = sum(1 for c in reversed_changes if "fail" not in c.note and "missing" not in c.note)
        console.print(f"[green]+[/green] reverted {ok} change(s)")
        for c in reversed_changes:
            if "fail" in c.note or "missing" in c.note:
                err_console.print(f"  [yellow]·[/yellow] {c.kind}: {c.note}")
        return

    if not system or not game or not to:
        err_console.print(f"[red]--system, --game, --to are all required for {verb}.[/red]")
        sys.exit(1)
    _check_config(config)

    try:
        plan = plan_rename(
            config, system, game, to,
            clone=clone,
            new_display_name=display_name or "",
        )
    except ValueError as e:
        err_console.print(f"[red]Cannot {verb}:[/red] {e}")
        sys.exit(1)

    console.print(Panel(
        f" {verb} — {system}: {game} -> {to} "
        + ("[cyan](clone — keeps original)[/cyan]" if clone else ""),
        style="bold blue",
    ))
    _print_rename_table(plan, title=f"Plan ({len(plan.file_changes)} change(s))")

    if not apply_changes:
        console.print(
            f"\n[yellow]Dry-run only.[/yellow] "
            f"Re-run with [cyan]--apply[/cyan] to {verb}."
        )
        return

    out_path = Path(output_dir) if output_dir else None
    try:
        applied, manifest = apply_rename(plan, config, output_dir=out_path)
    except (FileExistsError, RuntimeError, OSError) as e:
        from ._errors import humanize_oserror
        msg = humanize_oserror(e, action="apply the rename") if isinstance(e, OSError) else str(e)
        err_console.print(f"[red]Aborted:[/red] {msg}")
        sys.exit(1)

    console.print(f"\n[green]+[/green] {verb} complete — {len(applied)} change(s)")
    if verbose:
        for ch in applied:
            if ch.src and ch.dest:
                action = "copied" if clone else "moved"
                console.print(f"[dim]  {ch.kind}: {ch.src} → {ch.dest}[/dim]")
            elif ch.note:
                console.print(f"[dim]  {ch.kind}: {ch.note}[/dim]")
    if manifest:
        console.print(
            f"Manifest: {manifest.name}\n"
            f"  Run [cyan]spindoctor {verb} --undo {manifest}[/cyan] to revert."
        )


@cli.command("rename")
@click.option("--system", "-s", default=None, help="System where the game lives.")
@click.option("--game", default=None, help="Existing ROM/DB name to rename.")
@click.option("--to", "to_name", default=None, help="New ROM/DB name.")
@click.option("--display-name", default=None,
              help="New <description> text. Defaults to the existing description.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Execute the rename. Without this flag, dry-run only.")
@click.option("--undo", "undo_manifest", default=None, type=click.Path(exists=True),
              help="Reverse the rename described by this manifest.")
@click.option("--list-manifests", "list_manifests_flag", is_flag=True,
              help="List rename/clone manifests on disk and exit.")
@click.option("--output-dir", default=None, type=click.Path(),
              help="Write the edited DB into <output-dir>/Databases/<system>/ "
                   "instead of the live HyperSpin tree.")
@click.option("--verbose", is_flag=True,
              help="Print each file path moved / updated after the rename completes.")
def rename_cmd(system, game, to_name, display_name, apply_changes, undo_manifest,
               list_manifests_flag, output_dir, verbose):
    """Rename a game's ROM, DB entry, and every media file in one shot.

    \b
    Examples:
      spindoctor rename --system MAME --game "1942" --to "1942 (USA)"
      spindoctor rename --system MAME --game "1942" --to "1942 (USA)" \\
                        --display-name "1942 (USA)" --apply
      spindoctor rename --undo ~/.spindoctor/renames/rename-20260428_120000.json
      spindoctor rename --list-manifests
    """
    _do_rename_or_clone(
        clone=False,
        system=system, game=game, to=to_name, display_name=display_name,
        apply_changes=apply_changes, undo_manifest=undo_manifest,
        list_manifests_flag=list_manifests_flag, output_dir=output_dir,
        verbose=verbose,
    )


@cli.command("clone")
@click.option("--system", "-s", default=None, help="System where the game lives.")
@click.option("--game", default=None, help="Existing ROM/DB name to duplicate.")
@click.option("--to", "to_name", default=None, help="Name for the duplicate.")
@click.option("--display-name", default=None,
              help="<description> text for the new entry.")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Execute the clone. Without this flag, dry-run only.")
@click.option("--undo", "undo_manifest", default=None, type=click.Path(exists=True),
              help="Reverse the clone described by this manifest.")
@click.option("--list-manifests", "list_manifests_flag", is_flag=True,
              help="List rename/clone manifests on disk and exit.")
@click.option("--output-dir", default=None, type=click.Path(),
              help="Write the edited DB into <output-dir>/Databases/<system>/ "
                   "instead of the live HyperSpin tree.")
@click.option("--verbose", is_flag=True,
              help="Print each file path copied / updated after the clone completes.")
def clone_cmd(system, game, to_name, display_name, apply_changes, undo_manifest,
              list_manifests_flag, output_dir, verbose):
    """Duplicate a game (ROM, DB entry, all media) under a new name.

    \b
    Examples:
      spindoctor clone --system MAME --game "1942" --to "1942 (Hack)"
      spindoctor clone --system MAME --game "1942" --to "1942 (Hack)" \\
                       --display-name "1942 (Speed Hack)" --apply
      spindoctor clone --undo ~/.spindoctor/renames/rename-20260428_120000.json
      spindoctor clone --list-manifests
    """
    _do_rename_or_clone(
        clone=True,
        system=system, game=game, to=to_name, display_name=display_name,
        apply_changes=apply_changes, undo_manifest=undo_manifest,
        list_manifests_flag=list_manifests_flag, output_dir=output_dir,
        verbose=verbose,
    )


# ─── tools-audit ──────────────────────────────────────────────────────────────

@cli.command("tools-audit")
@click.option("--extra-path", "extra_paths", multiple=True, type=click.Path(),
              help="Additional directory to scan for installed tools. "
                   "Repeatable.")
@click.option("--max-depth", type=int, default=4, show_default=True,
              help="How deep to descend into each scanned root.")
@click.option("--show-unknown", is_flag=True,
              help="List .exe files we found but don't recognise — useful "
                   "for telling us what to add to the registry.")
def tools_audit_cmd(extra_paths, max_depth, show_unknown):
    """Audit third-party arcade tools installed on this PC.

    \b
    Read-only.  Scans HyperSpin\\Tools, RocketLauncher\\Modules, the
    emulators tree, Program Files and the Start Menu for known utilities
    (Tur-RemoveDupes, FatMatch, Sinden, DemulShooter, …) and reports
    whether spindoctor already covers each tool's job.

    Best run on the arcade cabinet itself.  Add --extra-path for any
    custom install locations the auto-scan misses.
    """
    from . import tools_audit as ta

    config = _cfg()
    roots = ta.default_scan_roots(config)
    extras = [Path(p) for p in extra_paths]
    result = ta.scan_for_tools(
        roots, extra_roots=extras, max_depth=max_depth,
        report_unknown=show_unknown,
    )

    console.print(Panel(" Tools audit ", style="bold blue"))

    if result.scanned_roots:
        console.print("[dim]Scanned:[/dim]")
        for r in result.scanned_roots:
            console.print(f"  [dim]·[/dim] {r}")
    if result.missing_roots:
        console.print("[dim]Skipped (not present):[/dim]")
        for r in result.missing_roots:
            console.print(f"  [dim]·[/dim] {r}")

    if not result.findings:
        console.print("\n[yellow]No known tools detected.[/yellow]")
        if not result.scanned_roots:
            console.print("[dim]Tip:[/dim] configure hyperspin_dir and "
                          "rocketlauncher_dir, or pass --extra-path.")
        return

    grouped = result.by_category()
    for category in ta.CATEGORY_ORDER:
        items = grouped.get(category)
        if not items:
            continue
        console.print(f"\n[bold]{ta.category_label(category)}[/bold]")
        tbl = Table(box=box.SIMPLE, show_header=True)
        tbl.add_column("Tool", style="yellow", no_wrap=False)
        tbl.add_column("Replaced by", style="cyan", no_wrap=False)
        tbl.add_column("Notes", style="dim", no_wrap=False)
        tbl.add_column("Path", style="dim", no_wrap=False)
        for finding in items:
            replaced = finding.entry.superseded_by or "—"
            paths = "\n".join(str(p) for p in (
                finding.matched_executables or finding.install_paths
            )[:3])
            tbl.add_row(finding.entry.name, replaced,
                        finding.entry.notes or "", paths)
        console.print(tbl)

    if show_unknown and result.unknown_executables:
        console.print(f"\n[bold]{ta.category_label(ta.CATEGORY_UNKNOWN)}[/bold]")
        console.print(f"[dim]({len(result.unknown_executables)} unrecognised "
                      "executables under scanned roots — first 50 shown)[/dim]")
        for u in result.unknown_executables[:50]:
            console.print(f"  · {u.path}")

    superseded = [f for cat in (ta.CATEGORY_ROM_TOOL,)
                  for f in grouped.get(cat, [])
                  if f.entry.superseded_by]
    if superseded:
        console.print(
            f"\n[green]→[/green] {len(superseded)} ROM/media tool(s) above "
            "are fully covered by spindoctor commands. Safe to uninstall "
            "once you've confirmed the spindoctor equivalent works for you."
        )


# ─── lightgun ─────────────────────────────────────────────────────────────────

@cli.group("lightgun")
def lightgun_group():
    """Sinden / DemulShooter wiring for lightgun-enabled systems.

    \b
    `lightgun detect`    — find Sinden + DemulShooter, seed config from
                           any RL INIs already wired to DemulShooter.
    `lightgun audit`     — show DemulShooter wiring status per system.
    `lightgun configure` — wire one system's RL INI (dry-run by default).
    """


@lightgun_group.command("detect")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Persist detected lightgun systems into spindoctor config.")
@click.option("--verbose", is_flag=True, help="Print install paths and pre-wired system count.")
def lightgun_detect(apply_changes, verbose):
    """Detect installed lightgun gear and pre-wired systems."""
    from . import lightgun as lg

    config = _cfg()
    install = lg.detect_lightgun_install(config)

    grid = Table.grid(padding=(0, 2))
    grid.add_row("[cyan]Sinden software:[/cyan]",
                 str(install.sinden_software_dir) if install.has_sinden
                 else "[red]not found[/red]")
    grid.add_row("[cyan]DemulShooter:[/cyan]",
                 str(install.demulshooter_exe) if install.has_demulshooter
                 else "[red]not found[/red]")
    grid.add_row("[cyan]Arcade Guns Utility:[/cyan]",
                 str(install.arcade_guns_dir) if install.arcade_guns_dir
                 else "[dim]not found[/dim]")
    console.print(grid)

    pre_wired = lg.detect_lightgun_systems(config)
    already_marked = set(config.lightgun_systems())
    new_systems = [s for s in pre_wired if s not in already_marked]

    if pre_wired:
        console.print(f"\n[bold]Systems already wired to DemulShooter[/bold] "
                      f"({len(pre_wired)}):")
        for s in pre_wired:
            mark = " [dim](already in config)[/dim]" if s in already_marked else ""
            console.print(f"  · {s}{mark}")
    else:
        console.print("\n[dim]No systems found with DemulShooter Pre_Launch_App "
                      "wiring.[/dim]")

    if new_systems and not apply_changes:
        console.print(f"\n[yellow]DRY RUN[/yellow] — would mark "
                      f"{len(new_systems)} system(s) as lightgun in config: "
                      f"{', '.join(new_systems)}")
        console.print("[dim]Re-run with --apply to persist.[/dim]")
    elif new_systems and apply_changes:
        for s in new_systems:
            config.set_lightgun(s, True)
        save_config(config)
        console.print(f"\n[green]✓[/green] Marked {len(new_systems)} "
                      f"system(s) as lightgun in spindoctor config.")
    if verbose:
        console.print(
            f"[dim][verbose] sinden={install.sinden_software_dir or 'not found'}, "
            f"demulshooter={install.demulshooter_exe or 'not found'}, "
            f"pre-wired={len(pre_wired)}, new={len(new_systems)}[/dim]"
        )


@lightgun_group.command("audit")
def lightgun_audit():
    """Show DemulShooter wiring status for every lightgun system in config."""
    from . import lightgun as lg

    config = _cfg()
    systems = config.lightgun_systems()
    if not systems:
        console.print("[yellow]No lightgun systems configured.[/yellow] "
                      "Run [cyan]spindoctor lightgun detect --apply[/cyan] "
                      "or set [cyan]system_overrides[].lightgun = true[/cyan].")
        return

    install = lg.detect_lightgun_install(config)
    if not install.has_demulshooter:
        console.print("[red]DemulShooter not found on this PC.[/red] "
                      "Audit will still report INI status, but configure "
                      "will fail until DemulShooter is installed.")

    tbl = Table(box=box.ROUNDED)
    tbl.add_column("System", style="cyan")
    tbl.add_column("INI", style="dim")
    tbl.add_column("Pre_Launch_App")
    tbl.add_column("Target")
    tbl.add_column("Post_Launch_App")
    for s in systems:
        status = lg.audit_system_wiring(s, config)
        if not status:
            tbl.add_row(s, "[red]missing[/red]", "—", "—", "—")
            continue
        pre = "[green]wired[/green]" if status.pre_launch else "[red]none[/red]"
        post = "[green]wired[/green]" if status.post_launch else "[yellow]none[/yellow]"
        tbl.add_row(
            s, status.ini_path.name, pre, status.target or "—", post,
        )
    console.print(tbl)


@lightgun_group.command("configure")
@click.option("--system", "-s", required=True,
              help="HyperSpin system name to wire up.")
@click.option("--target", default=None,
              help="DemulShooter -target value. Auto-detected for known systems.")
@click.option("--extra-args", default=None,
              help="Extra args appended to DemulShooter command "
                   "(default: from config or '-noresize').")
@click.option("--apply", "apply_changes", is_flag=True,
              help="Write the INI changes. Without this flag, dry-run only.")
@click.option("--verbose", is_flag=True, help="Print the INI path and Pre/Post launch commands written.")
def lightgun_configure(system, target, extra_args, apply_changes, verbose):
    """Wire DemulShooter pre/post-launch hooks into a system's RL INI."""
    from . import lightgun as lg

    config = _cfg()
    install = lg.detect_lightgun_install(config)
    if config.demulshooter_path:
        # Honour user override even if auto-detect missed it.
        forced = Path(config.demulshooter_path)
        if forced.exists():
            install.demulshooter_exe = forced

    args = (extra_args
            or config.demulshooter_extra_args
            or lg.DEFAULT_DEMULSHOOTER_ARGS)
    try:
        plan = lg.plan_wire_system(
            system, config, install,
            target_override=target, extra_args=args,
        )
    except ValueError as e:
        err_console.print(f"[red]{e}[/red]")
        sys.exit(1)

    console.print(Panel(f" Lightgun configure: {system} ", style="bold blue"))
    grid = Table.grid(padding=(0, 2))
    grid.add_row("[cyan]Target:[/cyan]", plan.target)
    grid.add_row("[cyan]INI path:[/cyan]", str(plan.ini_path))
    grid.add_row("[cyan]Pre_Launch_App:[/cyan]", plan.pre_launch_command)
    grid.add_row("[cyan]Post_Launch_App:[/cyan]", plan.post_launch_command)
    console.print(grid)
    for note in plan.notes:
        console.print(f"  [yellow]·[/yellow] {note}")

    if not apply_changes:
        console.print("\n[yellow]DRY RUN[/yellow] — re-run with --apply "
                      "to write the INI.")
        return

    written = lg.apply_wire_plan(plan, config)
    config.set_lightgun(system, True)
    save_config(config)
    console.print(f"\n[green]✓[/green] Wrote DemulShooter hooks to "
                  f"[cyan]{written}[/cyan] and marked '{system}' as a "
                  "lightgun system in spindoctor config.")
    if verbose:
        console.print(f"[dim][verbose] INI: {plan.ini_path}[/dim]")
        console.print(f"[dim][verbose] Pre_Launch_App={plan.pre_launch_command}[/dim]")
        console.print(f"[dim][verbose] Post_Launch_App={plan.post_launch_command}[/dim]")


# ─── find-global ──────────────────────────────────────────────────────────────

@cli.command("find-global")
@click.argument("query")
@click.option("--limit", type=int, default=50, show_default=True,
              help="Max results per system.")
@click.option("--exact", is_flag=True,
              help="Match only when the query equals the title (case-insensitive).")
def find_global(query: str, limit: int, exact: bool):
    """Search every configured system's HyperSpin database for *query*.

    Replaces Hypersearch — type a title, get every system that has it.
    """
    config = _cfg()
    _check_config(config)
    systems = get_systems(config)
    if not systems:
        err_console.print("[red]No systems configured.[/red]")
        sys.exit(1)

    q = query.lower()
    tbl = Table(box=box.ROUNDED, title=f"Matches for '{query}'")
    tbl.add_column("System", style="cyan")
    tbl.add_column("Title", style="yellow")
    tbl.add_column("Description", style="dim")

    total = 0
    skipped: list[tuple[str, str]] = []
    for sys_name in systems:
        try:
            db = load_database(sys_name, config.databases_dir)
        except Exception as exc:  # noqa: BLE001 — report, don't suppress
            # The original code silently skipped systems whose XML
            # failed to parse — users wondered why "Mario" matched on
            # NES but not SNES with an obvious typo in the file. Keep
            # the loop going so other systems still match, but
            # surface what was skipped at the bottom.
            skipped.append((sys_name, f"{type(exc).__name__}: {exc}"))
            continue
        per_system = 0
        for name, entry in sorted(db.games().items()):
            haystack = f"{name} {entry.description}".lower()
            if exact:
                hit = (q == name.lower() or q == entry.description.lower())
            else:
                hit = q in haystack
            if not hit:
                continue
            tbl.add_row(sys_name, name, entry.description or "")
            total += 1
            per_system += 1
            if per_system >= limit:
                break

    if total == 0:
        console.print(f"[yellow]No matches for '{query}'.[/yellow]")
    else:
        console.print(tbl)
        console.print(f"[dim]{total} match(es) across {len(systems)} system(s).[/dim]")
    if skipped:
        console.print(
            f"[red]Skipped {len(skipped)} database(s) due to load errors:[/red]"
        )
        for sys_name, reason in skipped:
            console.print(f"  [dim]{sys_name}:[/dim] [yellow]{reason}[/yellow]")
